-- Empty choices mean not yet chosen, never fabricated ordinary-user defaults.
alter table public.account_settings drop constraint if exists account_preferences_choices;
alter table public.account_settings add constraint account_preferences_choices check (
 coalesce(preferences->>'distance' in ('','Nearby','5 miles','10 miles')
 and preferences->>'group' in ('','One-on-one','Small groups','Either'),false));

create or replace function public.reconciliation_chapters(p jsonb, prefs jsonb)
returns jsonb language plpgsql immutable set search_path='' as $$
declare identity jsonb; birth date;
begin
 if p is null or p='null'::jsonb then return '[]'; end if;
 identity := jsonb_build_object('username',p->'username','display_name',p->'display_name','bio',p->'bio','avatar_url',p->'avatar_url');
 if not public.valid_account_identity(identity) then return '[]'; end if;
 if jsonb_typeof(p->'interests') is distinct from 'array' then return '[0]'; end if;
 if (select count(distinct btrim(value #>> '{}')) from jsonb_array_elements(p->'interests')) < 3 then return '[0]'; end if;
 if jsonb_typeof(prefs->'intents') is distinct from 'array' then return '[0,1]'; end if;
 if jsonb_array_length(prefs->'intents')=0 then return '[0,1]'; end if;
 if coalesce(prefs->>'distance','') not in ('Nearby','5 miles','10 miles')
  or coalesce(prefs->>'group','') not in ('One-on-one','Small groups','Either')
  or coalesce(length(btrim(p->>'location_city')),0)=0
  or jsonb_typeof(p->'availability') is distinct from 'array' then return '[0,1,2]'; end if;
 if jsonb_array_length(p->'availability')=0 or coalesce(p->>'birthdate','') !~ '^\d{4}-\d{2}-\d{2}$' then return '[0,1,2]'; end if;
 begin birth := (p->>'birthdate')::date;
 exception when others then return '[0,1,2]'; end;
 if to_char(birth,'YYYY-MM-DD')<>p->>'birthdate' then return '[0,1,2]'; end if;
 return '[0,1,2,3]';
end $$;
revoke all on function public.reconciliation_chapters(jsonb,jsonb) from public, anon, authenticated;

create or replace function public.get_account() returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare actor uuid:=auth.uid(); saved public.account_settings; p jsonb; identity jsonb; prefs jsonb;
begin
 if actor is null then raise exception 'Not authenticated' using errcode='28000'; end if;
 select * into saved from public.account_settings where user_id=actor;
 p := public.get_matchmaking_profile();
 identity := public.get_account_profile();
 if identity is not null then
  p := coalesce(nullif(p,'null'::jsonb),'{"birthdate":null,"location_city":null,"interests":[],"availability":[]}'::jsonb) || identity;
 end if;
 prefs := coalesce(saved.preferences,'{"intents":[],"usual":[],"distance":"","group":""}'::jsonb);
 return jsonb_build_object('profile',p,'preferences',prefs,
  'settings',coalesce(saved.settings,'{"notifications":true,"availability":true,"discoverable":true,"location":false}'::jsonb),
  'completed',public.reconciliation_chapters(p,prefs));
end $$;

create or replace function public.save_account(account_in jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare actor uuid:=auth.uid(); p jsonb:=account_in->'profile'; prefs jsonb:=account_in->'preferences';
 settings_in jsonb:=account_in->'settings'; chapters jsonb:=account_in->'completed'; previous jsonb; n int; old_n int;
begin
 if actor is null then raise exception 'Not authenticated' using errcode='28000'; end if;
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'READ COMMITTED required' using errcode='25001'; end if;
 -- Always namespace BEFORE actor/row locks, including compatibility RPCs.
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('profile-username-namespace',0));
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('account:'||actor::text,0));
 if jsonb_typeof(account_in) is distinct from 'object' then raise exception 'Invalid account' using errcode='22023'; end if;
 if (select count(*) from jsonb_object_keys(account_in))<>4 or not account_in ?& array['profile','preferences','settings','completed'] then raise exception 'Invalid account fields' using errcode='22023'; end if;
 if jsonb_typeof(p) is distinct from 'object' or jsonb_typeof(prefs) is distinct from 'object' or jsonb_typeof(settings_in) is distinct from 'object' or jsonb_typeof(chapters) is distinct from 'array' then raise exception 'Invalid account document' using errcode='22023'; end if;
 if (select count(*) from jsonb_object_keys(prefs))<>4 or not prefs ?& array['intents','usual','distance','group']
  or jsonb_typeof(prefs->'intents') is distinct from 'array' or jsonb_typeof(prefs->'usual') is distinct from 'array'
  or coalesce(prefs->>'distance','?') not in ('','Nearby','5 miles','10 miles') or coalesce(prefs->>'group','?') not in ('','One-on-one','Small groups','Either') then raise exception 'Invalid preferences' using errcode='22023'; end if;
 if jsonb_array_length(prefs->'intents')>20 or jsonb_array_length(prefs->'usual')>4
  or exists(select from jsonb_array_elements(prefs->'intents') v where jsonb_typeof(v)<>'string' or length(btrim(v #>> '{}')) not between 1 and 120)
  or (select count(*)<>count(distinct btrim(value #>> '{}')) from jsonb_array_elements(prefs->'intents'))
  or exists(select from jsonb_array_elements(prefs->'usual') v where jsonb_typeof(v)<>'string' or v #>> '{}' not in ('Mornings','Afternoons','Evenings','Weekends')) then raise exception 'Invalid preference values' using errcode='22023'; end if;
 if (select count(*) from jsonb_object_keys(settings_in))<>4 or not settings_in ?& array['notifications','availability','discoverable','location']
  or exists(select from jsonb_each(settings_in) v where jsonb_typeof(v.value)<>'boolean') then raise exception 'Invalid settings' using errcode='22023'; end if;
 n:=jsonb_array_length(chapters);
 if n>4 or exists(select from jsonb_array_elements(chapters) with ordinality v(value,i) where value<>to_jsonb(i-1)) then raise exception 'Invalid chapter sequence' using errcode='22023'; end if;
 previous:=public.get_account(); old_n:=jsonb_array_length(previous->'completed');
 if n<old_n or n>old_n+1 or jsonb_array_length(public.reconciliation_chapters(p,prefs))<greatest(n,old_n) then raise exception 'Required fields or sequential progression missing' using errcode='22023'; end if;
 -- Original canonical implementation retains symmetric username reservation and projector.
 perform public.reconciliation_identity_write(jsonb_build_object('username',p->'username','display_name',p->'display_name','bio',p->'bio','avatar_url',p->'avatar_url'));
 -- Original profile implementation validates dates, bounds, labels, windows and overlap.
 -- Any failure rolls back canonical identity AND private settings in this transaction.
 perform public.reconciliation_profile_write(p);
 insert into public.account_settings(user_id,preferences,settings,completed) values(actor,prefs,settings_in,chapters)
 on conflict(user_id) do update set preferences=excluded.preferences,settings=excluded.settings,completed=excluded.completed,updated_at=now();
 return public.get_account();
end $$;

create or replace function public.save_account_profile(profile_in jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare account jsonb; p jsonb;
begin
 if auth.uid() is null then raise exception 'Not authenticated' using errcode='28000'; end if;
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'READ COMMITTED required' using errcode='25001'; end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('profile-username-namespace',0));
 if not public.valid_account_identity(profile_in) then raise exception 'Invalid identity' using errcode='22023'; end if;
 account:=public.get_account(); p:=coalesce(nullif(account->'profile','null'::jsonb),'{"birthdate":null,"location_city":null,"interests":[],"availability":[]}'::jsonb)||profile_in;
 account:=jsonb_set(account,'{profile}',p);
 if account->'completed'='[]'::jsonb then account:=jsonb_set(account,'{completed}','[0]'); end if;
 perform public.save_account(account);
 return public.get_account_profile();
end $$;
create or replace function public.save_matchmaking_profile(profile_in jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare account jsonb; identity jsonb;
begin
 if auth.uid() is null then raise exception 'Not authenticated' using errcode='28000'; end if;
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'READ COMMITTED required' using errcode='25001'; end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('profile-username-namespace',0));
 account:=public.get_account(); identity:=public.get_account_profile();
 -- Compatibility matching writes never override canonical identity.
 if identity is not null then profile_in:=profile_in||identity; end if;
 account:=jsonb_set(account,'{profile}',profile_in);
 if account->'completed'='[]'::jsonb then account:=jsonb_set(account,'{completed}','[0]'); end if;
 perform public.save_account(account);
 return public.get_matchmaking_profile();
end $$;
revoke all on function public.get_account(), public.save_account(jsonb), public.save_account_profile(jsonb), public.save_matchmaking_profile(jsonb) from public, anon, authenticated;
grant execute on function public.get_account(), public.save_account(jsonb), public.save_account_profile(jsonb), public.save_matchmaking_profile(jsonb) to authenticated;

-- Idempotent marker mapping; never overwrite identity, preferences, settings or vectors.
update public.account_settings s set completed=public.reconciliation_chapters(
 (select jsonb_build_object('username',p.username,'display_name',p.display_name,'bio',p.bio,'avatar_url',p.avatar_url,
 'birthdate',p.birthdate,'location_city',p.location_city,'interests',(select coalesce(jsonb_agg(i.text),'[]') from public.user_interests i where i.profile_id=p.id),
 'availability',(select coalesce(jsonb_agg(jsonb_build_object('dow',a.dow,'start_time',a.start_time,'end_time',a.end_time)),'[]') from public.availability a where a.profile_id=p.id)) from public.profiles p where p.id=s.user_id),s.preferences);
-- Missing settings rows need no fabricated choices or bulk profile rewrites:
-- get_account maps their valid stored prefix; the next real chapter save persists it.

-- Optional derived enrichment: retain labels, never invent vectors or disable triggers.
create or replace function public.user_interests_embed()
returns trigger language plpgsql set search_path=public,extensions as $$
begin
 begin
  perform set_config('http.curlopt_timeout_ms','2000',true);
  new.embedding:=public.get_gemini_embedding(new.text);
 exception when others then new.embedding:=null;
 end;
 return new;
end $$;


-- docs/profile-details-migration.sql

set local lock_timeout = '3s';
set local statement_timeout = '30s';

do $$ begin
  if current_setting('server_encoding') <> 'UTF8' then
    raise exception 'Profile details require UTF8' using errcode='22023';
  end if;
end $$;

-- Pebble comparison v1, byte-exact after fixed whitespace/case mapping. This is
-- NOT full Unicode case folding. Unlisted scalars are unchanged; all valid
-- scalar labels remain supported. No locale casing/regex or normalization.
create function public.profile_language_key(value_in text)
returns text language plpgsql immutable set search_path = '' as $$
declare
  fold_ranges constant jsonb := '[[65,90,1,32],[192,214,1,32],[216,222,1,32],[256,302,2,1],[306,310,2,1],[313,327,2,1],[330,374,2,1],[377,381,2,1],[461,475,2,1],[478,494,2,1],[498,500,2,1],[504,542,2,1],[546,562,2,1],[913,929,1,32],[931,939,1,32],[1024,1039,1,80],[1040,1071,1,32],[1120,1152,2,1],[1162,1214,2,1],[1217,1229,2,1],[1232,1326,2,1],[1329,1366,1,48],[7680,7828,2,1],[7840,7934,2,1],[65313,65338,1,32],[66560,66599,1,40],[66736,66771,1,40],[68736,68786,1,64],[71840,71871,1,32],[93760,93791,1,32],[125184,125217,1,34]]';
  fold_exceptions constant jsonb := '{"181":"μ","223":"ss","304":"i\u0307","376":"ÿ","383":"s","902":"ά","904":"έ","905":"ή","906":"ί","908":"ό","910":"ύ","911":"ώ","962":"σ","976":"β","977":"θ","981":"φ","982":"π","1008":"κ","1009":"ρ","1013":"ε","7838":"ss","8486":"ω","8490":"k","8491":"å"}';
  whitespace_points constant jsonb := '[9,10,11,12,13,32,160,5760,8192,8193,8194,8195,8196,8197,8198,8199,8200,8201,8202,8232,8233,8239,8287,12288,65279]';
  spaces text := ''; clean text; result text := ''; item jsonb; point integer;
  mapped integer; exception_in text; position_in integer;
begin
  if value_in is null then return null; end if;
  for item in select value from jsonb_array_elements(whitespace_points) loop
    spaces := spaces || chr((item #>> '{}')::integer);
  end loop;
  clean := btrim(value_in, spaces);
  for position_in in 1..char_length(clean) loop
    point := ascii(substr(clean,position_in,1));
    exception_in := fold_exceptions->>point::text;
    if exception_in is not null then result := result || exception_in; continue; end if;
    mapped := point;
    for item in select value from jsonb_array_elements(fold_ranges) loop
      if point between (item->>0)::integer and (item->>1)::integer
        and (point - (item->>0)::integer) % (item->>2)::integer = 0 then
        mapped := point + (item->>3)::integer; exit;
      end if;
    end loop;
    result := result || chr(mapped);
  end loop;
  return result;
end $$;
revoke all on function public.profile_language_key(text) from public, anon, authenticated;

-- Paired with the TypeScript corpus. These assertions execute ONLY if the
-- parent installs the candidate; static Vitest parsing is not SQL evidence.
do $$
declare
  key_corpus constant jsonb := '[["\uFEFF English\u00A0","english"],["\u00A0\uFEFF",""],["I","i"],["i","i"],["İ","i\u0307"],["ı","ı"],["ΟΣ","οσ"],["ος","οσ"],["οσ","οσ"],["FRANÇAIS","français"],["РУССКИЙ","русский"],["日本語","日本語"],["𐐀𐐨😀","𐐨𐐨😀"],["Straße","strasse"],["STRASSE","strasse"],["é","é"],["e\u0301","e\u0301"],["\u0085English\u0085","\u0085english\u0085"],["\u200BEnglish\u200B","\u200Benglish\u200B"],["Ꭰꭰ","Ꭰꭰ"]]';
  pair jsonb;
begin
  for pair in select value from jsonb_array_elements(key_corpus) loop
    if (public.profile_language_key(pair->>0) collate "C") is distinct from ((pair->>1) collate "C") then
      raise exception 'Profile language key corpus failed' using errcode='22023';
    end if;
  end loop;
end $$;

create function public.valid_profile_facts(facts_in jsonb)
returns boolean language plpgsql immutable set search_path = '' as $$
declare item jsonb; label text; seen text[] := '{}'::text[]; visibility_in jsonb;
begin
  if jsonb_typeof(facts_in) is distinct from 'object' then return false; end if;
  if (select count(*) from jsonb_object_keys(facts_in)) <> 4
    or not facts_in ?& array['education','occupation','languages','visibility'] then return false; end if;
  if jsonb_typeof(facts_in->'education') is distinct from 'string'
    or jsonb_typeof(facts_in->'occupation') is distinct from 'string'
    or char_length(facts_in->>'education') > 120
    or char_length(facts_in->>'occupation') > 120
    or jsonb_typeof(facts_in->'languages') is distinct from 'array' then return false; end if;
  if jsonb_array_length(facts_in->'languages') > 12 then return false; end if;
  for item in select value from jsonb_array_elements(facts_in->'languages') loop
    if jsonb_typeof(item) is distinct from 'string' then return false; end if;
    -- Comparison key only: preserve exact stored values and their order.
    label := public.profile_language_key(item #>> '{}');
    if (label collate "C") = '' or char_length(item #>> '{}') > 60 or (label collate "C") = any(seen) then return false; end if;
    seen := array_append(seen, label);
  end loop;
  visibility_in := facts_in->'visibility';
  if jsonb_typeof(visibility_in) is distinct from 'object' then return false; end if;
  if (select count(*) from jsonb_object_keys(visibility_in)) <> 3
    or not visibility_in ?& array['education','occupation','languages'] then return false; end if;
  if exists(select 1 from jsonb_each(visibility_in) v where jsonb_typeof(v.value) is distinct from 'boolean') then return false; end if;
  return true;
end $$;
revoke all on function public.valid_profile_facts(jsonb) from public, anon, authenticated;

-- Deliberately no IF NOT EXISTS / CREATE OR REPLACE: fail rather than silently
-- adopting preexisting objects, owners or grants. Parent reviews collisions.
create table public.profile_details (
  user_id uuid primary key references auth.users(id) on delete cascade,
  revision bigint not null default 0 check (revision between 0 and 9007199254740991),
  facts jsonb not null check (public.valid_profile_facts(facts))
);
alter table public.profile_details enable row level security;
revoke all on public.profile_details from public, anon, authenticated;
-- No browser SELECT/DML grants or policies. Owner reads are RPC-only too.

create function public.get_profile_details()
returns jsonb language plpgsql security definer set search_path = '' as $$
declare actor uuid := auth.uid(); result jsonb;
begin
  if actor is null then raise exception 'Authentication required' using errcode='28000'; end if;
  select jsonb_build_object('revision',d.revision,'facts',d.facts) into result
    from public.profile_details d where d.user_id = actor;
  -- Revision zero is a virtual empty resource, not a write or fabricated fact.
  return coalesce(result, '{"revision":0,"facts":{"education":"","occupation":"","languages":[],"visibility":{"education":false,"occupation":false,"languages":false}}}'::jsonb);
end $$;
revoke all on function public.get_profile_details() from public, anon, authenticated;
grant execute on function public.get_profile_details() to authenticated;

create function public.save_profile_details(details_in jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare actor uuid := auth.uid(); expected_revision bigint;
begin
  if actor is null then raise exception 'Authentication required' using errcode='28000'; end if;
  if current_setting('transaction_isolation') <> 'read committed' then
    raise exception 'Profile details writes require READ COMMITTED' using errcode='25001'; end if;
  if jsonb_typeof(details_in) is distinct from 'object' then
    raise exception 'Invalid profile details' using errcode='22023'; end if;
  if (select count(*) from jsonb_object_keys(details_in)) <> 2
    or not details_in ?& array['expectedRevision','facts']
    or jsonb_typeof(details_in->'expectedRevision') is distinct from 'number'
    or not public.valid_profile_facts(details_in->'facts') then
    raise exception 'Invalid profile details' using errcode='22023'; end if;
  if (details_in->>'expectedRevision')::numeric < 0
    or (details_in->>'expectedRevision')::numeric >= 9007199254740991
    or trunc((details_in->>'expectedRevision')::numeric) <> (details_in->>'expectedRevision')::numeric then
    raise exception 'Invalid or exhausted revision' using errcode='22023'; end if;
  expected_revision := (details_in->>'expectedRevision')::numeric::bigint;
  -- Concurrent initial inserts serialize on the actor primary key. The UPDATE
  -- then compares the current revision, never just a prior unlocked SELECT.
  insert into public.profile_details(user_id,revision,facts)
    values(actor,0,'{"education":"","occupation":"","languages":[],"visibility":{"education":false,"occupation":false,"languages":false}}'::jsonb)
    on conflict(user_id) do nothing;
  update public.profile_details set facts = details_in->'facts', revision = revision + 1
    where user_id = actor and revision = expected_revision;
  if not found then
    -- Exception rolls back even a just-inserted revision-zero row.
    raise exception 'Profile details revision conflict' using errcode='PD409';
  end if;
  return public.get_profile_details();
end $$;
revoke all on function public.save_profile_details(jsonb) from public, anon, authenticated;
grant execute on function public.save_profile_details(jsonb) to authenticated;


-- docs/detailed-settings-migration.sql

set local lock_timeout = '3s';
set local statement_timeout = '30s';
do $$ begin
  if not exists(select 1 from pg_class where oid=to_regclass('public.account_settings') and relkind in ('r','p')) then
    raise exception 'Legacy account_settings prerequisite missing' using errcode='22023';
  end if;
  if not has_table_privilege(current_user,'public.account_settings','SELECT')
    or (not exists(select 1 from pg_roles where rolname=current_user and (rolsuper or rolbypassrls))
      and not exists(select 1 from pg_class where oid='public.account_settings'::regclass and pg_get_userbyid(relowner)=current_user and not relforcerowsecurity)) then
    raise exception 'Reviewed persisted-master read owner required' using errcode='42501';
  end if;
end $$;

create function public.valid_detailed_settings(value_in jsonb)
returns boolean language plpgsql immutable set search_path = '' as $$
begin
  if jsonb_typeof(value_in) is distinct from 'object' then return false; end if;
  if (select count(*) from jsonb_object_keys(value_in)) <> 5
    or not value_in ?& array['messages','plans','matches','friendsDiscovery','datingDiscovery'] then return false; end if;
  return not exists(select 1 from jsonb_each(value_in) v where jsonb_typeof(v.value) is distinct from 'boolean');
end $$;
revoke all on function public.valid_detailed_settings(jsonb) from public, anon, authenticated;

-- Missing/malformed actual rows stay UNKNOWN. Never call get_account here: its
-- historical/reconciled fallback is default-on, not persisted new-mode consent.
create function public.detailed_settings_masters(value_in jsonb)
returns jsonb language plpgsql immutable set search_path = '' as $$
begin
  if jsonb_typeof(value_in) is distinct from 'object' then return null; end if;
  if (select count(*) from jsonb_object_keys(value_in)) <> 4
    or not value_in ?& array['notifications','availability','discoverable','location'] then return null; end if;
  if exists(select 1 from jsonb_each(value_in) v where jsonb_typeof(v.value) is distinct from 'boolean') then return null; end if;
  return jsonb_build_object('notifications',value_in->'notifications','discoverable',value_in->'discoverable');
end $$;
revoke all on function public.detailed_settings_masters(jsonb) from public, anon, authenticated;

create function public.effective_detailed_settings(choices_in jsonb, masters_in jsonb)
returns jsonb language sql immutable set search_path = '' as $$
  select jsonb_build_object(
    'messages',coalesce((masters_in->>'notifications')::boolean,false) and (choices_in->>'messages')::boolean,
    'plans',coalesce((masters_in->>'notifications')::boolean,false) and (choices_in->>'plans')::boolean,
    'matches',coalesce((masters_in->>'notifications')::boolean,false) and (choices_in->>'matches')::boolean,
    'friendsDiscovery',coalesce((masters_in->>'discoverable')::boolean,false) and (choices_in->>'friendsDiscovery')::boolean,
    'datingDiscovery',coalesce((masters_in->>'discoverable')::boolean,false) and (choices_in->>'datingDiscovery')::boolean);
$$;
revoke all on function public.effective_detailed_settings(jsonb,jsonb) from public, anon, authenticated;

create table public.detailed_settings (
  user_id uuid primary key references auth.users(id) on delete cascade,
  revision bigint not null check (revision between 1 and 9007199254740991),
  settings jsonb not null check (public.valid_detailed_settings(settings))
);
alter table public.detailed_settings enable row level security;
revoke all on public.detailed_settings from public, anon, authenticated;
-- No browser table/column grants or policies. CREATE collisions abort rather
-- than adopting unknown existing objects/owners. Parent reviews inherited ACLs.

create function public.get_detailed_settings()
returns jsonb language plpgsql security definer set search_path = '' as $$
declare actor uuid := auth.uid(); result jsonb;
begin
  if actor is null then raise exception 'Authentication required' using errcode='28000'; end if;
  -- Both sources and the computed policy use one SQL statement snapshot. This
  -- adds no legacy writer/advisory/row locks and cannot resume downtime.
  select jsonb_build_object('revision',coalesce(d.revision,0),'settings',v.choices,
    'masters',v.masters,'effective',public.effective_detailed_settings(v.choices,v.masters)) into result
  from (values(actor)) me(id)
  left join public.detailed_settings d on d.user_id=me.id
  left join public.account_settings a on a.user_id=me.id
  cross join lateral (select
    coalesce(d.settings,'{"messages":false,"plans":false,"matches":false,"friendsDiscovery":false,"datingDiscovery":false}'::jsonb) as choices,
    public.detailed_settings_masters(a.settings) as masters) v;
  return result;
end $$;
revoke all on function public.get_detailed_settings() from public, anon, authenticated;
grant execute on function public.get_detailed_settings() to authenticated;

create function public.save_detailed_settings(settings_in jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare actor uuid := auth.uid(); expected_revision bigint;
begin
  if actor is null then raise exception 'Authentication required' using errcode='28000'; end if;
  if current_setting('transaction_isolation') <> 'read committed' then
    raise exception 'Detailed settings writes require READ COMMITTED' using errcode='25001'; end if;
  if jsonb_typeof(settings_in) is distinct from 'object' then raise exception 'Invalid detailed settings' using errcode='22023'; end if;
  if (select count(*) from jsonb_object_keys(settings_in)) <> 2 or not settings_in ?& array['expectedRevision','settings']
    or jsonb_typeof(settings_in->'expectedRevision') is distinct from 'number'
    or not public.valid_detailed_settings(settings_in->'settings') then
    raise exception 'Invalid detailed settings' using errcode='22023'; end if;
  if (settings_in->>'expectedRevision')::numeric < 0 or (settings_in->>'expectedRevision')::numeric >= 9007199254740991
    or trunc((settings_in->>'expectedRevision')::numeric) <> (settings_in->>'expectedRevision')::numeric then
    raise exception 'Invalid or exhausted revision' using errcode='22023'; end if;
  expected_revision := (settings_in->>'expectedRevision')::numeric::bigint;
  if expected_revision=0 then
    insert into public.detailed_settings(user_id,revision,settings) values(actor,1,settings_in->'settings') on conflict(user_id) do nothing;
  else
    update public.detailed_settings set settings=settings_in->'settings',revision=revision+1
      where user_id=actor and revision = expected_revision;
  end if;
  if not found then raise exception 'Detailed settings revision conflict' using errcode='DS409'; end if;
  return public.get_detailed_settings();
end $$;
revoke all on function public.save_detailed_settings(jsonb) from public, anon, authenticated;
grant execute on function public.save_detailed_settings(jsonb) to authenticated;


-- docs/uuid-safety-owner-migration.sql

set local lock_timeout='3s';
set local statement_timeout='30s';
do $$ declare t text; signature text; begin
 if current_setting('server_encoding')<>'UTF8' or to_regnamespace('safety_private') is not null
 or to_regprocedure('public.messaging_history(uuid,uuid,bigint,bigint)') is null
 or to_regprocedure('public.messaging_send(uuid,uuid,text,uuid)') is null
 or to_regprocedure('public.messaging_sync_connection()') is null
 then raise exception 'Native UUID messaging prerequisites missing' using errcode='22023';end if;
 foreach t in array array['profiles','blocks','connections','conversations','messages','conversation_participants','dating_matches'] loop
  if not exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname=t and c.relkind='r' and pg_get_userbyid(c.relowner)=current_user and not c.relforcerowsecurity) then
   raise exception 'Native messaging table owner mismatch: %',t using errcode='42501';end if;
 end loop;
 if (select atttypid from pg_attribute where attrelid='public.conversations'::regclass and attname='id' and not attisdropped) is distinct from 'uuid'::regtype
 or (select atttypid from pg_attribute where attrelid='public.messages'::regclass and attname='id' and not attisdropped) is distinct from 'uuid'::regtype
 or (select atttypid from pg_attribute where attrelid='public.messages'::regclass and attname='seq' and not attisdropped) is distinct from 'bigint'::regtype
 or exists(select 1 from public.blocks where blocker_id=blocked_id)
 then raise exception 'Native messaging shape mismatch' using errcode='22023';end if;
 if not exists(select 1 from pg_trigger where tgrelid='public.connections'::regclass and tgname='messaging_sync_connection' and tgfoid='public.messaging_sync_connection()'::regprocedure and tgenabled='O') then
  raise exception 'Native connection lifecycle trigger missing' using errcode='22023';end if;
 foreach signature in array array['public.messaging_history(uuid,uuid,bigint,bigint)','public.messaging_send(uuid,uuid,text,uuid)','public.messaging_mark_read(uuid,uuid,bigint)'] loop
  if has_function_privilege('anon',signature,'EXECUTE') or has_function_privilege('authenticated',signature,'EXECUTE')
  or not has_function_privilege('service_role',signature,'EXECUTE') then raise exception 'Native messaging ACL mismatch' using errcode='42501';end if;
 end loop;
end $$;
create function public.safety_pair_allowed(first_id uuid,second_id uuid) returns boolean language sql stable security definer set search_path='' as $$
 select first_id is not null and second_id is not null and first_id<>second_id and not exists(select 1 from public.blocks b where (b.blocker_id=first_id and b.blocked_id=second_id) or (b.blocker_id=second_id and b.blocked_id=first_id));
$$;
revoke all on function public.safety_pair_allowed(uuid,uuid) from public,anon,authenticated;
create schema safety_private;
revoke all on schema safety_private from public,anon,authenticated;

create function safety_private.lock_pair(a uuid,b uuid) returns void language plpgsql volatile security definer set search_path='' as $$
begin
  if current_setting('transaction_isolation')<>'read committed' then raise exception 'READ COMMITTED required' using errcode='25001'; end if;
  if a is null or b is null or a=b then raise exception 'Invalid pair' using errcode='22023'; end if;
  -- Lock canonical FK endpoints in UUID order before the advisory pair key.
  -- Normal owner writes cannot hold the pair while waiting for profile deletion.
  perform 1 from public.profiles p where p.id in (a,b) order by p.id for key share;
  -- One canonical unordered-pair key, held through commit. Hash collisions only
  -- over-serialize; they cannot admit an excluded pair. No table-wide lock.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('pebble.safety.pair.v1:'||least(a,b)::text||':'||greatest(a,b)::text,0));
end $$;
create function safety_private.actor() returns uuid language plpgsql stable set search_path='' as $$
declare actor uuid:=auth.uid(); begin
  if actor is null then raise exception 'Authentication required' using errcode='28000'; end if;
  return actor;
end $$;
create function safety_private.maintenance() returns boolean language sql stable set search_path='' as $$
  -- SECURITY DEFINER current_user is not evidence of maintenance authority.
  -- SET ROLE authenticated on an executor session must still exercise browser checks.
  select current_setting('role') not in ('anon','authenticated') and exists(
    select 1 from pg_catalog.pg_roles where rolname=session_user and (rolsuper or rolbypassrls));
$$;
create table safety_private.revoked_connections(connection_id bigint primary key);
-- Not a block store: an existing relationship ID is permanently quarantined on
-- block so unblock cannot reactivate its acceptance. No row/history deletion.
-- No FK lock on the connection row: pair serialization governs this marker.
create table safety_private.reports (
  actor_id uuid not null references auth.users(id) on delete cascade,
  request_id uuid not null, id uuid not null unique default pg_catalog.gen_random_uuid(),
  target_id uuid not null, reason text not null check (reason in ('Harassment','Inappropriate content','Impersonation','Safety concern','Other')),
  context text not null check (char_length(context)<=1000), received_at timestamptz not null default statement_timestamp(),
  primary key(actor_id,request_id)
);
-- Target intentionally has no profile FK: report intake is not an existence/name oracle.
create index safety_reports_actor_time on safety_private.reports(actor_id,received_at);
alter table safety_private.revoked_connections enable row level security;
alter table safety_private.reports enable row level security;
revoke all on safety_private.revoked_connections,safety_private.reports from public,anon,authenticated;

create function safety_private.contact_allowed(a uuid,b uuid) returns boolean language sql stable security definer set search_path='' as $$
  select public.safety_pair_allowed(a,b) and exists(select 1 from public.connections c
    where c.user_a=least(a,b) and c.user_b=greatest(a,b) and c.status='accepted'
      and not exists(select 1 from safety_private.revoked_connections r where r.connection_id=c.id));
$$;
create function safety_private.guard_blocks() returns trigger language plpgsql volatile security definer set search_path='' as $$
declare a uuid; b uuid; actor uuid:=auth.uid(); cleanup boolean;
begin
  if tg_op='UPDATE' then raise exception 'Block identity/metadata is immutable' using errcode='42501'; end if;
  if tg_op='DELETE' then a:=old.blocker_id; b:=old.blocked_id; else a:=new.blocker_id; b:=new.blocked_id; end if;
  cleanup:=tg_op='DELETE' and (not exists(select 1 from public.profiles where id=a) or not exists(select 1 from public.profiles where id=b));
  if not cleanup and not safety_private.maintenance() and actor is distinct from a then raise exception 'Owner block mutation required' using errcode='42501'; end if;
  perform safety_private.lock_pair(a,b);
  if tg_op='INSERT' then
    new.created_at:=statement_timestamp();
    insert into safety_private.revoked_connections(connection_id)
      select c.id from public.connections c where c.user_a=least(a,b) and c.user_b=greatest(a,b) on conflict do nothing;
    return new;
  end if;
  return old;
end $$;
create trigger safety_blocks_guard before insert or update or delete on public.blocks for each row execute function safety_private.guard_blocks();
-- Existing accepted/pending relationships of already-blocked pairs are also inert.
insert into safety_private.revoked_connections(connection_id)
  select c.id from public.connections c where exists(select 1 from public.blocks b where (b.blocker_id=c.user_a and b.blocked_id=c.user_b) or (b.blocker_id=c.user_b and b.blocked_id=c.user_a));

create function safety_private.guard_connections() returns trigger language plpgsql volatile security definer set search_path='' as $$
declare a uuid; b uuid; actor uuid:=auth.uid(); cleanup boolean; begin
  if tg_op='DELETE' then a:=old.user_a; b:=old.user_b; else a:=new.user_a; b:=new.user_b; end if;
  if tg_op='UPDATE' and row(new.id,new.user_a,new.user_b,new.initiated_by,new.created_at) is distinct from row(old.id,old.user_a,old.user_b,old.initiated_by,old.created_at) then raise exception 'Immutable connection identity' using errcode='42501'; end if;
  cleanup:=tg_op='DELETE' and (not exists(select 1 from public.profiles where id=a) or not exists(select 1 from public.profiles where id=b));
  if not cleanup and not safety_private.maintenance() and (actor is null or (actor<>a and actor<>b)) then raise exception 'Connection unavailable' using errcode='42501'; end if;
  perform safety_private.lock_pair(a,b);
  if tg_op='DELETE' then return old; end if;
  if not public.safety_pair_allowed(a,b) then raise exception 'Contact unavailable' using errcode='42501'; end if;
  if tg_op='INSERT' then
    if new.initiated_by is distinct from actor or new.status<>'pending' then raise exception 'Actor-bound pending request required' using errcode='42501'; end if;
    new.created_at:=statement_timestamp(); new.responded_at:=null;
  else
    if old.status<>'pending' or new.status<>'accepted' or actor=old.initiated_by
      or exists(select 1 from safety_private.revoked_connections where connection_id=old.id) then raise exception 'Acceptance unavailable' using errcode='42501'; end if;
    new.responded_at:=statement_timestamp();
  end if;
  return new;
end $$;
-- After the historical insert normalizer/rate trigger; BEFORE any after-update
-- conversation creation. UPDATE/ON CONFLICT retargeting cannot bypass this guard.
create trigger zz_safety_connections_guard before insert or update or delete on public.connections for each row execute function safety_private.guard_connections();

-- The existing UUID messaging tables and lifecycle triggers are retained.
create function safety_private.guard_dating() returns trigger language plpgsql volatile security definer set search_path='' as $$
declare actor uuid:=auth.uid(); begin
  if tg_op='UPDATE' and row(new.id,new.user_a,new.user_b,new.initiated_by,new.created_at) is distinct from row(old.id,old.user_a,old.user_b,old.initiated_by,old.created_at) then raise exception 'Immutable Dating pair identity' using errcode='42501'; end if;
  if actor is null or (actor is distinct from new.user_a and actor is distinct from new.user_b) then raise exception 'Dating unavailable' using errcode='42501'; end if;
  perform safety_private.lock_pair(new.user_a,new.user_b);
  if not public.safety_pair_allowed(new.user_a,new.user_b) then raise exception 'Dating unavailable' using errcode='42501'; end if;
  -- No real Dating admission until aggregate/reciprocity/discovery are consumed.
  raise exception 'Legacy Dating admissions unavailable' using errcode='42501';
end $$;
create trigger safety_dating_guard before insert or update on public.dating_matches for each row execute function safety_private.guard_dating();

create function public.get_owner_block_state(target_in uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=safety_private.actor(); begin
  if target_in is null or target_in=actor then raise exception 'Invalid target' using errcode='22023'; end if;
  return jsonb_build_object('targetId',target_in,'outgoingBlocked',exists(select 1 from public.blocks where blocker_id=actor and blocked_id=target_in),'enforcement','contact-mutations-only');
end $$;
create or replace function public.get_owner_blocklist() returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=safety_private.actor(); result jsonb; begin
  select coalesce(jsonb_agg(jsonb_build_object('targetId',b.blocked_id,'displayName',null,'blockedAt',case when isfinite(b.created_at) then b.created_at else null end) order by b.blocked_id),'[]'::jsonb) into result
    from public.blocks b where b.blocker_id=actor;
  return jsonb_build_object('enforcement','contact-mutations-only','blocks',result);
end $$;
create function public.block_owner_target(target_in uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=safety_private.actor(); begin
  perform safety_private.lock_pair(actor,target_in);
  insert into public.blocks(blocker_id,blocked_id) values(actor,target_in) on conflict(blocker_id,blocked_id) do nothing;
  return public.get_owner_block_state(target_in);
end $$;
create function public.unblock_owner_target(target_in uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=safety_private.actor(); begin
  perform safety_private.lock_pair(actor,target_in);
  delete from public.blocks where blocker_id=actor and blocked_id=target_in;
  -- No connection recreation, marker removal, conversation deletion or reverse unblock.
  return public.get_owner_block_state(target_in);
end $$;

create function safety_private.report_receipt(r safety_private.reports) returns jsonb language sql stable set search_path='' as $$
  select jsonb_build_object('id',(r).id,'requestId',(r).request_id,'targetId',(r).target_id,'receivedAt',to_char((r).received_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'status','received');
$$;
create function public.get_owner_safety_report(request_id_in uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=safety_private.actor(); r safety_private.reports; begin
  select saved.* into r from safety_private.reports saved where saved.actor_id=actor and saved.request_id=request_id_in;
  if not found then raise exception 'Owner receipt unavailable' using errcode='PT404'; end if;
  return safety_private.report_receipt(r);
end $$;
create function public.submit_safety_report(report_in jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=safety_private.actor(); request_key uuid; target uuid; k text; r safety_private.reports;
begin
  if current_setting('transaction_isolation')<>'read committed' then raise exception 'READ COMMITTED required' using errcode='25001'; end if;
  if jsonb_typeof(report_in) is distinct from 'object' then raise exception 'Invalid report' using errcode='22023'; end if;
  if (select count(*) from jsonb_object_keys(report_in))<>4 or not report_in ?& array['requestId','targetId','reason','context'] then raise exception 'Invalid report fields' using errcode='22023'; end if;
  foreach k in array array['requestId','targetId'] loop
    if jsonb_typeof(report_in->k) is distinct from 'string' or char_length(report_in->>k)<>36
      or (report_in->>k collate "C") !~ '^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$' then raise exception 'Invalid report UUID' using errcode='22023'; end if;
  end loop;
  if jsonb_typeof(report_in->'reason') is distinct from 'string' or (report_in->>'reason' collate "C") not in ('Harassment','Inappropriate content','Impersonation','Safety concern','Other')
    or jsonb_typeof(report_in->'context') is distinct from 'string' or char_length(report_in->>'context')>1000 then raise exception 'Invalid report text' using errcode='22023'; end if;
  request_key:=(report_in->>'requestId')::uuid; target:=(report_in->>'targetId')::uuid;
  if target=actor then raise exception 'Invalid report target' using errcode='22023'; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('pebble.safety.report.v1:'||actor::text,0));
  select saved.* into r from safety_private.reports saved where saved.actor_id=actor and saved.request_id=request_key;
  if found then
    if r.target_id<>target or (r.reason collate "C") is distinct from (report_in->>'reason' collate "C") or (r.context collate "C") is distinct from (report_in->>'context' collate "C") then raise exception 'Report request conflict' using errcode='SR409'; end if;
    return safety_private.report_receipt(r);
  end if;
  if (select count(*) from safety_private.reports where actor_id=actor and received_at>statement_timestamp()-interval '1 hour')>=5
    or (select count(*) from safety_private.reports where actor_id=actor and received_at>statement_timestamp()-interval '24 hours')>=20 then raise exception 'Report intake rate limited' using errcode='SR429'; end if;
  insert into safety_private.reports(actor_id,request_id,target_id,reason,context) values(actor,request_key,target,report_in->>'reason',report_in->>'context') returning * into r;
  return safety_private.report_receipt(r);
end $$;

-- Withdraw browser bypasses, including column grants. Old permissive policies do
-- not override a missing grant. Privileged legacy DML still traverses the guards.
do $$ declare t text; cols text; seq text; r text; sig text; begin
  foreach t in array array['blocks','connections','conversations','messages','dating_matches'] loop
    execute format('revoke all on table public.%I from public,anon,authenticated',t);
    select string_agg(quote_ident(attname),',') into cols from pg_catalog.pg_attribute where attrelid=('public.'||t)::regclass and attnum>0 and not attisdropped;
    execute format('revoke all (%s) on table public.%I from public,anon,authenticated',cols,t);
    seq:=case when t='blocks' then null else pg_get_serial_sequence('public.'||t,'id') end;
    if seq is not null then execute format('revoke all on sequence %s from public,anon,authenticated',seq); end if;
    foreach r in array array['anon','authenticated'] loop
      if seq is not null and has_sequence_privilege(r::name,seq,'SELECT,USAGE,UPDATE') then raise exception 'Inherited sequence bypass requires review: % %',r,seq using errcode='42501'; end if;
      if has_table_privilege(r::name,'public.'||t,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') or has_any_column_privilege(r::name,'public.'||t,'SELECT') or has_any_column_privilege(r::name,'public.'||t,'INSERT') or has_any_column_privilege(r::name,'public.'||t,'UPDATE') or has_any_column_privilege(r::name,'public.'||t,'REFERENCES') then raise exception 'Inherited browser bypass requires review: % %',r,t using errcode='42501'; end if;
    end loop;
  end loop;
  -- Historical read/receipt policy is undecided: withdraw, do not delete history
  -- or fabricate empty inbox/unread success. Legacy Dating stays unavailable.
  foreach sig in array array['public.get_incoming_requests()','public.get_sent_requests()','public.get_my_conversations()','public.get_unread_count()','public.mark_conversation_read(bigint)','public.get_dating_match()','public.request_dating_match(uuid)','public.accept_dating_match(bigint)','public.end_dating_match(bigint)'] loop
    if to_regprocedure(sig) is not null then
      execute format('revoke all on function %s from public,anon,authenticated',sig);
      foreach r in array array['anon','authenticated'] loop
        if has_function_privilege(r::name,sig,'EXECUTE') then raise exception 'Inherited legacy RPC bypass requires review: %',sig using errcode='42501'; end if;
      end loop;
    end if;
  end loop;
end $$;
revoke all on all functions in schema safety_private from public,anon,authenticated;
revoke all on function public.get_owner_blocklist(),public.get_owner_block_state(uuid),public.block_owner_target(uuid),public.unblock_owner_target(uuid),public.submit_safety_report(jsonb),public.get_owner_safety_report(uuid) from public,anon,authenticated;
grant execute on function public.get_owner_blocklist(),public.get_owner_block_state(uuid),public.block_owner_target(uuid),public.unblock_owner_target(uuid),public.submit_safety_report(jsonb),public.get_owner_safety_report(uuid) to authenticated;
do $$ declare r text; t text; f record; sig text; begin
  foreach r in array array['anon','authenticated'] loop
    if has_schema_privilege(r::name,'safety_private','USAGE,CREATE') then raise exception 'Inherited private schema access requires review' using errcode='42501'; end if;
    foreach t in array array['safety_private.reports','safety_private.revoked_connections'] loop
      if has_table_privilege(r::name,t,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') or has_any_column_privilege(r::name,t,'SELECT') or has_any_column_privilege(r::name,t,'INSERT') or has_any_column_privilege(r::name,t,'UPDATE') or has_any_column_privilege(r::name,t,'REFERENCES') then raise exception 'Inherited private table access requires review' using errcode='42501'; end if;
    end loop;
    for f in select p.oid from pg_catalog.pg_proc p where p.pronamespace='safety_private'::regnamespace loop
      if has_function_privilege(r::name,f.oid,'EXECUTE') then raise exception 'Inherited private helper access requires review' using errcode='42501'; end if;
    end loop;
  end loop;
  foreach sig in array array['public.get_owner_blocklist()','public.get_owner_block_state(uuid)','public.block_owner_target(uuid)','public.unblock_owner_target(uuid)','public.submit_safety_report(jsonb)','public.get_owner_safety_report(uuid)'] loop
    if has_function_privilege('anon',sig,'EXECUTE') then raise exception 'Inherited anonymous RPC access requires review' using errcode='42501'; end if;
  end loop;
end $$;


-- docs/uuid-social-contact-migration.sql

set local lock_timeout='3s';
set local statement_timeout='30s';
do $$ begin
 if to_regprocedure('safety_private.lock_pair(uuid,uuid)') is null or to_regprocedure('public.messaging_list_conversations(uuid,integer)') is null
 or to_regprocedure('public.messaging_history(uuid,uuid,bigint,bigint)') is null
 or to_regprocedure('public.messaging_send(uuid,uuid,text,uuid)') is null
 or to_regprocedure('public.messaging_mark_read(uuid,uuid,bigint)') is null
 or to_regprocedure('public.messaging_activity(uuid)') is null
 or has_schema_privilege('anon','public','CREATE') or has_schema_privilege('authenticated','public','CREATE') then
 raise exception 'Native actor messaging prerequisites missing' using errcode='22023';end if;
 if exists(select 1 from public.messages where seq not between 1 and 9007199254740991)
 or exists(select 1 from public.conversation_participants where last_read_seq not between 0 and 9007199254740991) then
 raise exception 'Native message positions exceed frontend contract' using errcode='22023';end if;
end $$;
create schema social_private;
revoke all on schema social_private from public,anon,authenticated;
create table social_private.send_requests (
 actor_id uuid not null references auth.users(id) on delete cascade,
 request_id uuid not null,
 message_id uuid not null references public.messages(id) on delete cascade,
 primary key(actor_id,request_id)
);
alter table social_private.send_requests enable row level security;
revoke all on social_private.send_requests from public,anon,authenticated;
create function social_private.discoverable(person uuid) returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.profiles p join public.account_settings a on a.user_id=p.id
 where p.id=person and p.is_active and public.detailed_settings_masters(a.settings)->>'discoverable'='true'
 and p.birthdate between date '0001-01-01' and date '9999-12-31'
 and p.birthdate<=(statement_timestamp() at time zone 'America/New_York')::date-interval '18 years'
 and char_length(p.username) between 1 and 80 and char_length(p.display_name) between 1 and 120
 and public.profile_language_key(p.username)<>'' and public.profile_language_key(p.display_name)<>''
 and coalesce(char_length(p.bio),0)<=1000 and char_length(p.location_city)<=120 and public.profile_language_key(p.location_city)<>''
 and (select count(*) from public.user_interests i where i.profile_id=p.id) between 3 and 30
 and not exists(select 1 from public.user_interests i where i.profile_id=p.id and (char_length(i.text)>120 or public.profile_language_key(i.text)=''))
 and (select count(*) from public.availability w where w.profile_id=p.id) between 1 and 56
 and not exists(select 1 from public.availability w where w.profile_id=p.id and (w.start_time::text !~ '^(([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9])$' or w.end_time::text !~ '^(([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9]|24:00:00)$'))
 and not exists(select 1 from public.availability w join public.availability x on x.profile_id=w.profile_id and x.id>w.id where w.profile_id=p.id and w.dow=x.dow and w.start_time<x.end_time and x.start_time<w.end_time)
 and jsonb_typeof(a.preferences->'intents')='array' and jsonb_array_length(a.preferences->'intents') between 1 and 20
 and not exists(select 1 from jsonb_array_elements(a.preferences->'intents') item where jsonb_typeof(item)<>'string' or char_length(item #>> '{}')>120 or public.profile_language_key(item #>> '{}')='')
 and a.preferences->>'distance' in('Nearby','5 miles','10 miles') and a.preferences->>'group' in('One-on-one','Small groups','Either'));
$$;
-- Existing connections authorize history, not contact with an inactive profile.
create function social_private.contact_allowed(a uuid,b uuid) returns boolean language sql stable security definer set search_path='' as $$
 select safety_private.contact_allowed(a,b) and (select count(*)=2 from public.profiles p where p.id in(a,b) and p.is_active);
$$;
create function social_private.lock_pair(a uuid,b uuid) returns void language plpgsql volatile security definer set search_path='' as $$
begin
 -- Canonical profile saves lock the profile before replacing its child facts.
 -- SHARE also serializes non-key is_active edits; the base FK fence is KEY SHARE.
 perform 1 from public.profiles p where p.id in(a,b) order by p.id for share;
 perform safety_private.lock_pair(a,b);
end $$;
create function social_private.person(person uuid,viewer uuid,read_seq bigint default 0) returns jsonb language sql stable security definer set search_path='' as $$
 select jsonb_build_object('id',person,'display_name',case when person=viewer or public.safety_pair_allowed(person,viewer) then coalesce(p.display_name,'Account '||person::text) else 'Account '||person::text end,
 'avatar_url',case when (person=viewer or public.safety_pair_allowed(person,viewer)) and p.avatar_url ~ '^https://' then p.avatar_url else null end,'last_read_seq',read_seq)
 from (values(person)) me(id) left join public.profiles p on p.id=me.id;
$$;

create function social_private.peer(conversation_in uuid,actor uuid) returns uuid language sql stable security definer set search_path='' as $$
 select other.user_id from public.conversations c
 join public.conversation_participants mine on mine.conversation_id=c.id and mine.user_id=actor and mine.left_at is null
 join public.conversation_participants other on other.conversation_id=c.id and other.user_id<>actor
 where c.id=conversation_in and c.kind='direct'
 and c.source_key='direct:'||least(actor,other.user_id)||':'||greatest(actor,other.user_id)
 limit 1;
$$;
create function social_private.participants(conversation_in uuid,actor uuid) returns jsonb language sql stable security definer set search_path='' as $$
 select coalesce(jsonb_agg(social_private.person(p.user_id,actor,case when p.user_id=actor or social_private.contact_allowed(actor,p.user_id) then p.last_read_seq else 0 end) order by p.joined_at,p.user_id),'[]')
 from public.conversation_participants p where p.conversation_id=conversation_in and p.left_at is null;
$$;
create function social_private.connection_state(actor uuid,target uuid) returns jsonb language sql stable security definer set search_path='' as $$
 select coalesce((select jsonb_build_object('status',case when c.status='accepted' then 'connected' when c.initiated_by=actor then 'sent' else 'incoming' end,
 'conversationId',case when c.status='accepted' then chat.id else null end)
 from public.connections c left join public.conversations chat on chat.source_key='direct:'||c.user_a||':'||c.user_b
 where c.user_a=least(actor,target) and c.user_b=greatest(actor,target) and public.safety_pair_allowed(actor,target)
 and not exists(select 1 from safety_private.revoked_connections r where r.connection_id=c.id)), '{"status":"none","conversationId":null}'::jsonb);
$$;
create function public.social_connection(target_in uuid,action_in text) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=safety_private.actor(); c public.connections;
begin
 if target_in is null or target_in=actor or action_in not in('get','request','accept','remove') or action_in is null then raise exception 'Invalid connection request' using errcode='22023'; end if;
 if action_in='get' then return social_private.connection_state(actor,target_in); end if;
 perform social_private.lock_pair(actor,target_in);
 select * into c from public.connections where user_a=least(actor,target_in) and user_b=greatest(actor,target_in);
 perform 1 from public.account_settings prefs where prefs.user_id in(actor,target_in) order by prefs.user_id for share;
 if action_in='remove' then
  delete from public.connections where id=c.id;
  return social_private.connection_state(actor,target_in);
 end if;
 if not public.safety_pair_allowed(actor,target_in) or not social_private.discoverable(actor) or not social_private.discoverable(target_in)
 or exists(select 1 from safety_private.revoked_connections r where r.connection_id=c.id) then raise exception 'Connection unavailable' using errcode='42501'; end if;
 if c.id is null then
  if action_in='accept' then raise exception 'No incoming request' using errcode='42501'; end if;
  insert into public.connections(user_a,user_b,initiated_by) values(least(actor,target_in),greatest(actor,target_in),actor);
 elsif c.status='pending' and c.initiated_by<>actor then
  update public.connections set status='accepted' where id=c.id;
 elsif action_in='accept' and c.status<>'accepted' then raise exception 'No incoming request' using errcode='42501';
 end if;
 return social_private.connection_state(actor,target_in);
end $$;
create function public.social_connection_list() returns jsonb language plpgsql stable security definer set search_path='' as $$
declare actor uuid:=safety_private.actor(); result jsonb;
begin
 select jsonb_build_object('incoming',coalesce(jsonb_agg(person||jsonb_build_object('requested_at',c.created_at) order by c.created_at desc,c.id) filter(where c.status='pending' and c.initiated_by<>actor),'[]'),
 'sent',coalesce(jsonb_agg(person||jsonb_build_object('requested_at',c.created_at) order by c.created_at desc,c.id) filter(where c.status='pending' and c.initiated_by=actor),'[]'),
 'connected',coalesce(jsonb_agg(person||jsonb_build_object('conversationId',social_private.connection_state(actor,other)->'conversationId') order by c.created_at desc,c.id) filter(where c.status='accepted'),'[]')) into result
 from public.connections c cross join lateral (select case when c.user_a=actor then c.user_b else c.user_a end other) peer
 cross join lateral (select social_private.person(other,actor)-'last_read_seq' person) projection
 where actor in(c.user_a,c.user_b) and public.safety_pair_allowed(c.user_a,c.user_b)
 and not exists(select 1 from safety_private.revoked_connections r where r.connection_id=c.id);
 return result;
end $$;

create function public.social_inbox(page_in integer default 1) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare actor uuid:=safety_private.actor(); result jsonb; items jsonb;
begin
 if page_in is null or page_in not between 1 and 10000 then raise exception 'Invalid inbox page' using errcode='22023';end if;
 result:=public.messaging_list_conversations(actor,page_in);
 select coalesce(jsonb_agg(jsonb_set(item,'{participants}',social_private.participants((item->>'id')::uuid,actor)) order by ord),'[]') into items
 from jsonb_array_elements(result->'conversations') with ordinality rows(item,ord);
 return jsonb_set(result,'{conversations}',items);
end $$;
create function public.social_history(conversation_in uuid,before_in bigint default null,after_in bigint default null) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare actor uuid:=safety_private.actor(); result jsonb; other uuid;
begin
 if (before_in is not null and after_in is not null) or before_in<1 or after_in<0 or coalesce(before_in,0)>9007199254740991 or coalesce(after_in,0)>9007199254740991 then raise exception 'Invalid message cursor' using errcode='22023';end if;
 result:=public.messaging_history(actor,conversation_in,before_in,after_in);
 other:=social_private.peer(conversation_in,actor);
 return result||jsonb_build_object('canSend',coalesce(other is not null and social_private.contact_allowed(actor,other),false),'participants',social_private.participants(conversation_in,actor));
end $$;
create function public.social_send(conversation_in uuid,body_in text,request_in uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=safety_private.actor(); other uuid; previous public.messages; result jsonb;
begin
 body_in:=regexp_replace(body_in,'^[[:space:]]+|[[:space:]]+$','','g');
 if body_in is null or public.profile_language_key(body_in)='' or (select coalesce(sum(case when ascii(ch)>65535 then 2 else 1 end),0) from regexp_split_to_table(body_in,'') ch)>2000 or request_in is null then raise exception 'Invalid message' using errcode='22023';end if;
 other:=social_private.peer(conversation_in,actor);
 if other is null then raise exception 'Conversation unavailable' using errcode='42501';end if;
 perform social_private.lock_pair(actor,other);
 if not social_private.contact_allowed(actor,other) then raise exception 'Contact unavailable' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('pebble.social.send.v1:'||actor::text||':'||request_in::text,0));
 select m.* into previous from social_private.send_requests r join public.messages m on m.id=r.message_id where r.actor_id=actor and r.request_id=request_in;
 if found then
  if previous.body<>body_in or previous.conversation_id<>conversation_in then raise exception 'Message request conflict' using errcode='SC409';end if;
  return to_jsonb(previous)-'client_request_id';
 end if;
 result:=public.messaging_send(actor,conversation_in,body_in,request_in);
 insert into social_private.send_requests(actor_id,request_id,message_id) values(actor,request_in,(result->>'id')::uuid);
 return result;
end $$;
create function public.social_read(conversation_in uuid,seq_in bigint) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=safety_private.actor(); other uuid; saved bigint;
begin
 if seq_in is null or seq_in not between 0 and 9007199254740991 then raise exception 'Invalid read position' using errcode='22023';end if;
 other:=social_private.peer(conversation_in,actor);
 if other is null then raise exception 'Conversation unavailable' using errcode='42501';end if;
 perform social_private.lock_pair(actor,other);
 if not social_private.contact_allowed(actor,other) then raise exception 'Contact unavailable' using errcode='42501';end if;
 if seq_in<>0 and not exists(select 1 from public.messages m where m.conversation_id=conversation_in and m.seq=seq_in and not public.messaging_hidden(actor,m.sender_id)) then raise exception 'Message unavailable' using errcode='42501';end if;
 saved:=public.messaging_mark_read(actor,conversation_in,seq_in);
 return jsonb_build_object('lastReadSeq',saved);
end $$;
create function public.social_activity() returns jsonb language plpgsql stable security definer set search_path='' as $$
declare actor uuid:=safety_private.actor(); result jsonb;begin
 result:=public.messaging_activity(actor);
 return result||jsonb_build_object('incomingRequests',jsonb_array_length(public.social_connection_list()->'incoming'));
end $$;
revoke all on all functions in schema social_private from public,anon,authenticated;
revoke all on function public.social_connection(uuid,text),public.social_connection_list(),public.social_inbox(integer),public.social_history(uuid,bigint,bigint),public.social_send(uuid,text,uuid),public.social_read(uuid,bigint),public.social_activity() from public,anon,authenticated;
grant execute on function public.social_connection(uuid,text),public.social_connection_list(),public.social_inbox(integer),public.social_history(uuid,bigint,bigint),public.social_send(uuid,text,uuid),public.social_read(uuid,bigint),public.social_activity() to authenticated;
do $$ declare r text; t text; f record; signature text; begin
 foreach r in array array['anon','authenticated'] loop
  if has_schema_privilege(r::name,'social_private','USAGE') then raise exception 'Inherited social schema grant' using errcode='42501'; end if;
  for t in select tablename from pg_catalog.pg_tables where schemaname='social_private' loop
   if has_table_privilege(r::name,'social_private.'||t,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')
    or has_any_column_privilege(r::name,'social_private.'||t,'SELECT,INSERT,UPDATE,REFERENCES') then raise exception 'Inherited social table grant' using errcode='42501'; end if;
  end loop;
  for f in select p.oid from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid=p.pronamespace where n.nspname='social_private' loop
   if has_function_privilege(r::name,f.oid,'EXECUTE') then raise exception 'Inherited social helper grant' using errcode='42501'; end if;
  end loop;
 end loop;
 foreach signature in array array['public.social_connection(uuid,text)','public.social_connection_list()','public.social_inbox(integer)','public.social_history(uuid,bigint,bigint)','public.social_send(uuid,text,uuid)','public.social_read(uuid,bigint)','public.social_activity()'] loop
  if has_function_privilege('anon',signature,'EXECUTE') or not has_function_privilege('authenticated',signature,'EXECUTE') then raise exception 'Social RPC privilege mismatch' using errcode='42501'; end if;
 end loop;
end $$;


-- docs/discovery-privacy-migration.sql

set local lock_timeout='3s';
set local statement_timeout='30s';
do $$ declare signature text; begin
 if to_regprocedure('social_private.discoverable(uuid)') is null or to_regprocedure('public.get_detailed_settings()') is null then raise exception 'Privacy prerequisites missing' using errcode='22023'; end if;
 foreach signature in array array['public.join_queue(text)','public.leave_queue()','public.express_event_interest(bigint,text)','public.withdraw_event_interest(bigint)','public.search_people(text,integer)','public.get_queue_status()','public.social_connection_list()','public.get_events_with_interest(text,text,integer)','public.get_event_matches(bigint)','public.get_recommended_meetups(integer)','event_group_private.profile_valid(uuid)'] loop
  if to_regprocedure(signature) is not null and not exists(select 1 from pg_catalog.pg_proc where oid=to_regprocedure(signature) and pg_get_userbyid(proowner)=current_user) then raise exception 'Privacy function owner mismatch: %',signature using errcode='42501'; end if;
 end loop;
 if has_schema_privilege('anon','public','CREATE') or has_schema_privilege('authenticated','public','CREATE') then raise exception 'Untrusted public schema' using errcode='42501'; end if;
end $$;
-- All profile/child writes go through existing actor-bound canonical saves. In
-- particular, users cannot forge coordinates, last-seen flags or readiness by DML.
do $$ declare t text; r text; a record; f text; seq text; begin
 foreach t in array array['profiles','user_interests','availability','queue_entries','event_interest','meetup_attendees','interaction_outcomes','meetups'] loop
  execute format('revoke all on table public.%I from public,anon,authenticated',t);
  for a in select attname from pg_catalog.pg_attribute where attrelid=('public.'||t)::regclass and attnum>0 and not attisdropped loop
   execute format('revoke select(%I),insert(%I),update(%I),references(%I) on public.%I from public,anon,authenticated',a.attname,a.attname,a.attname,a.attname,t);
  end loop;
  if exists(select 1 from pg_catalog.pg_attribute where attrelid=('public.'||t)::regclass and attname='id' and attidentity<>'') then
   seq:=pg_get_serial_sequence('public.'||t,'id'); execute format('revoke all on sequence %s from public,anon,authenticated',seq);
   foreach r in array array['anon','authenticated'] loop
    if has_sequence_privilege(r::name,seq,'SELECT,USAGE,UPDATE') then raise exception 'Inherited privacy sequence bypass: % %',r,seq using errcode='42501'; end if;
   end loop;
  end if;
  foreach r in array array['anon','authenticated'] loop
   if has_table_privilege(r::name,'public.'||t,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') or has_any_column_privilege(r::name,'public.'||t,'SELECT,INSERT,UPDATE,REFERENCES') then raise exception 'Inherited raw privacy bypass: % %',r,t using errcode='42501'; end if;
  end loop;
 end loop;
 -- No direct arbitrary-person scoring, profile-text, schedule, outcome or old
 -- queue projection RPC. Owner canonical getters never take another actor ID.
 foreach f in array array['public.user_interest_vector(uuid)','public.profile_text(uuid)','public.profile_embedding(uuid)','public.shared_interest_labels(uuid,uuid)',
 'public.availability_overlap_minutes(uuid,uuid)','public.social_reliability(uuid)','public.collaborative_fit(uuid,uuid)','public.person_friend_score(uuid,uuid)','public.person_dating_score(uuid,uuid)',
 'public.get_queue_match()','public.record_interaction(uuid,text,boolean,integer,boolean,boolean)','public.get_gemini_embedding(text)','public.meetup_embedding(bigint)'] loop
  if to_regprocedure(f) is not null then
   execute format('revoke all on function %s from public,anon,authenticated',f);
   foreach r in array array['anon','authenticated'] loop
    if has_function_privilege(r::name,f,'EXECUTE') then raise exception 'Inherited legacy privacy RPC bypass: % %',r,f using errcode='42501'; end if;
   end loop;
  end if;
 end loop;
end $$;
create function social_private.friends_discoverable(person uuid) returns boolean language sql stable security definer set search_path='' as $$
 select social_private.discoverable(person) and exists(select 1 from public.detailed_settings s where s.user_id=person and s.settings->>'friendsDiscovery'='true');
$$;
-- Historical membership authorizes old bodies, not live metadata about an
-- inactive, blocked or no-longer-connected peer. Pending requests have an
-- explicit current audience only while both owners remain discoverable.
create function social_private.profile_audience(viewer uuid,person uuid) returns boolean language sql stable security definer set search_path='' as $$
 select viewer=person or social_private.contact_allowed(viewer,person) or
 (public.safety_pair_allowed(viewer,person) and social_private.discoverable(viewer) and social_private.discoverable(person)
 and exists(select 1 from public.connections c where c.user_a=least(viewer,person) and c.user_b=greatest(viewer,person) and c.status='pending'
 and not exists(select 1 from safety_private.revoked_connections r where r.connection_id=c.id)));
$$;
create or replace function social_private.person(person uuid,viewer uuid,read_seq bigint default 0) returns jsonb language sql stable security definer set search_path='' as $$
 select jsonb_build_object('id',person,'display_name',case when social_private.profile_audience(viewer,person) then coalesce(p.display_name,'Account '||person::text) else 'Account '||person::text end,
 'avatar_url',case when social_private.profile_audience(viewer,person) and p.avatar_url ~ '^https://' then p.avatar_url else null end,'last_read_seq',read_seq)
 from (values(person)) me(id) left join public.profiles p on p.id=me.id;
$$;
create or replace function public.social_connection_list() returns jsonb language plpgsql stable security definer set search_path='' as $$
declare actor uuid:=safety_private.actor(); result jsonb;
begin
 select jsonb_build_object('incoming',coalesce(jsonb_agg(person||jsonb_build_object('requested_at',c.created_at) order by c.created_at desc,c.id) filter(where c.status='pending' and c.initiated_by<>actor),'[]'),
 'sent',coalesce(jsonb_agg(person||jsonb_build_object('requested_at',c.created_at) order by c.created_at desc,c.id) filter(where c.status='pending' and c.initiated_by=actor),'[]'),
 'connected',coalesce(jsonb_agg(person||jsonb_build_object('conversationId',social_private.connection_state(actor,other)->'conversationId') order by c.created_at desc,c.id) filter(where c.status='accepted'),'[]')) into result
 from public.connections c cross join lateral (select case when c.user_a=actor then c.user_b else c.user_a end other) peer
 cross join lateral (select social_private.person(other,actor)-'last_read_seq' person) projection
 where actor in(c.user_a,c.user_b) and (c.status='accepted' or (social_private.discoverable(actor) and social_private.discoverable(other))) and public.safety_pair_allowed(c.user_a,c.user_b)
 and not exists(select 1 from safety_private.revoked_connections r where r.connection_id=c.id);
 return result;
end $$;

-- Require current canonical audience even through a legacy elevated writer.
create function social_private.discovery_admission() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if safety_private.maintenance() then return new; end if;
 if tg_op='INSERT' or (tg_op='UPDATE' and new.status is distinct from old.status and new.status='accepted') then
  perform social_private.lock_pair(new.user_a,new.user_b);
  perform 1 from public.account_settings s where s.user_id in(new.user_a,new.user_b) order by s.user_id for share;
  if not social_private.discoverable(new.user_a) or not social_private.discoverable(new.user_b) then raise exception 'Connection unavailable' using errcode='42501'; end if;
 end if;
 return new;
end $$;
create trigger social_discovery_admission before insert or update on public.connections for each row execute function social_private.discovery_admission();
-- Legacy queue RPCs may enroll only their authenticated owner, never Dating.
create function social_private.queue_admission() returns trigger language plpgsql security definer set search_path='' as $$
declare actor uuid; begin
 if safety_private.maintenance() then return new; end if;
 actor:=safety_private.actor();
 if new.profile_id is distinct from actor or (tg_op='UPDATE' and new.profile_id is distinct from old.profile_id) or new.queue_type not in('matchmaking','downtime') then raise exception 'Queue unavailable' using errcode='42501'; end if;
 perform 1 from public.profiles p where p.id=actor for share;
 perform 1 from public.account_settings s where s.user_id=actor for share;
 if not social_private.discoverable(actor) or (new.queue_type='matchmaking' and not social_private.friends_discoverable(actor)) then raise exception 'Save your profile and enable discovery before joining' using errcode='PF409'; end if;
 new.joined_at:=statement_timestamp(); return new;
end $$;
create trigger social_queue_admission before insert or update on public.queue_entries for each row execute function social_private.queue_admission();
-- Public-event interest is not itself permission to discover/contact attendees.
-- Hosted-event block admission uses the same pair fence as block/unblock.
create function social_private.event_interest_admission() returns trigger language plpgsql security definer set search_path='' as $$
declare actor uuid; host uuid; begin
 if safety_private.maintenance() then return new; end if;
 actor:=safety_private.actor();
 if new.profile_id is distinct from actor or (tg_op='UPDATE' and row(new.profile_id,new.meetup_id,new.created_at) is distinct from row(old.profile_id,old.meetup_id,old.created_at)) then raise exception 'Event unavailable' using errcode='42501'; end if;
 select m.host_id into host from public.meetups m where m.id=new.meetup_id and m.is_public and m.starts_at>statement_timestamp() for share;
 if not found then raise exception 'Event unavailable' using errcode='42501'; end if;
 if host is not null and host<>actor then
  perform social_private.lock_pair(actor,host);
  if not public.safety_pair_allowed(actor,host) then raise exception 'Event unavailable' using errcode='42501'; end if;
 end if;
 if char_length(new.note)>1000 then raise exception 'Event note too long' using errcode='22023'; end if;
 if tg_op='INSERT' then new.created_at:=statement_timestamp(); end if;
 return new;
end $$;
create trigger social_event_interest_admission before insert or update on public.event_interest for each row execute function social_private.event_interest_admission();
-- Pin legacy writer resolution too: an empty-path caller or hostile pg_temp
-- must not redirect a SECURITY DEFINER write into a different relation.
create or replace function public.join_queue(qtype text) returns void language plpgsql security definer set search_path='' as $$
declare actor uuid:=safety_private.actor(); begin
 if qtype is null or qtype not in('matchmaking','downtime') then raise exception 'Queue unavailable' using errcode='42501'; end if;
 insert into public.queue_entries(profile_id,queue_type) values(actor,qtype)
 on conflict(profile_id) do update set queue_type=excluded.queue_type,joined_at=statement_timestamp();
end $$;
create or replace function public.leave_queue() returns void language plpgsql security definer set search_path='' as $$
declare actor uuid:=safety_private.actor(); begin delete from public.queue_entries where profile_id=actor; end $$;
create or replace function public.express_event_interest(meetup_id_in bigint,note_in text default null) returns void language plpgsql security definer set search_path='' as $$
declare actor uuid:=safety_private.actor(); begin
 if meetup_id_in is null or meetup_id_in<=0 or coalesce(char_length(note_in),0)>1000 then raise exception 'Invalid event interest' using errcode='22023'; end if;
 insert into public.event_interest(meetup_id,profile_id,note) values(meetup_id_in,actor,note_in)
 on conflict(meetup_id,profile_id) do update set note=excluded.note;
end $$;
create or replace function public.withdraw_event_interest(meetup_id_in bigint) returns void language plpgsql security definer set search_path='' as $$
declare actor uuid:=safety_private.actor(); begin
 if meetup_id_in is null or meetup_id_in<=0 then raise exception 'Invalid event' using errcode='22023'; end if;
 delete from public.event_interest where meetup_id=meetup_id_in and profile_id=actor;
end $$;
revoke all on function public.join_queue(text),public.leave_queue(),public.express_event_interest(bigint,text),public.withdraw_event_interest(bigint) from public,anon,authenticated;
grant execute on function public.join_queue(text),public.leave_queue(),public.express_event_interest(bigint,text),public.withdraw_event_interest(bigint) to authenticated;
-- Preserve legacy status signature but never expose a roster-size side channel.
create or replace function public.get_queue_status() returns table(my_queue text,others_in_my_queue integer)
language plpgsql stable security definer set search_path='' as $$
declare actor uuid:=safety_private.actor(); begin
 return query select (select q.queue_type from public.queue_entries q where q.profile_id=actor),null::integer;
end $$;
revoke all on function public.get_queue_status() from public,anon,authenticated;
grant execute on function public.get_queue_status() to authenticated;
create or replace function public.search_people(q text,max_results integer default 20)
returns table(profile_id uuid,username text,display_name text,bio text,location_city text,avatar_url text,connection_status text)
language plpgsql stable security definer set search_path='' as $$
declare actor uuid:=safety_private.actor(); begin
 if q is null or char_length(q) not between 2 and 120 or max_results is null or max_results not between 1 and 20 then raise exception 'Invalid search' using errcode='22023'; end if;
 if not social_private.friends_discoverable(actor) then return; end if;
 return query select p.id,p.username,p.display_name,p.bio,p.location_city,case when p.avatar_url ~ '^https://' then p.avatar_url else null end,
 case social_private.connection_state(actor,p.id)->>'status' when 'sent' then 'pending_sent' when 'incoming' then 'pending_received' when 'connected' then 'connected' else 'none' end
 from public.profiles p where p.id<>actor and social_private.friends_discoverable(p.id) and public.safety_pair_allowed(actor,p.id)
 and (p.username ilike '%'||q||'%' or p.display_name ilike '%'||q||'%' or p.location_city ilike '%'||q||'%'
 or exists(select 1 from public.user_interests i where i.profile_id=p.id and i.text ilike '%'||q||'%'))
 order by p.username,p.id limit max_results;
end $$;
revoke all on function public.search_people(text,integer) from public,anon,authenticated;
grant execute on function public.search_people(text,integer) to authenticated;
revoke all on all functions in schema social_private from public,anon,authenticated;

create or replace function public.get_events_with_interest(
  filter_category text default null,
  filter_city     text default null,
  max_results     int  default 30
)
returns table (
  event_id          bigint,
  title             text,
  description       text,
  category          text,
  location_name     text,
  location_city     text,
  starts_at         timestamptz,
  ends_at           timestamptz,
  host_id           uuid,
  host_username     text,
  host_display_name text,
  host_avatar_url   text,
  interested_count  int,
  i_am_interested   boolean
)
language plpgsql
stable
security definer
set search_path=pg_catalog,public,pg_temp
as $$
begin
  if auth.uid() is null then raise exception 'Authentication required' using errcode='28000'; end if;
  if max_results is null or max_results not between 1 and 30 or coalesce(char_length(filter_city),0)>120 or coalesce(char_length(filter_category),0)>120 then raise exception 'Invalid event filters' using errcode='22023'; end if;
  return query select
    m.id,
    m.title,
    m.description,
    m.category,
    m.location_name,
    p.location_city,
    m.starts_at,
    m.ends_at,
    m.host_id,
    p.username,
    p.display_name,
    p.avatar_url,
    (select count(*)::int from public.event_interest ei where ei.meetup_id = m.id and (ei.profile_id=auth.uid() or (social_private.discoverable(ei.profile_id) and public.safety_pair_allowed(auth.uid(),ei.profile_id)))),
    exists (
      select 1 from public.event_interest ei
      where ei.meetup_id = m.id and ei.profile_id = auth.uid()
    )
  from public.meetups m
  join public.profiles p on p.id = m.host_id
  where auth.uid() is not null and social_private.discoverable(auth.uid())
    and (m.host_id=auth.uid() or (social_private.discoverable(m.host_id) and public.safety_pair_allowed(auth.uid(),m.host_id)))
    and m.is_public = true
    and m.starts_at > now()
    and (filter_category is null or m.category = filter_category)
    and (filter_city is null or p.location_city = filter_city)
  order by m.starts_at asc
  limit max_results;
end;
$$;

create or replace function public.get_event_matches(meetup_id_in bigint)
returns table (
  profile_id       uuid,
  username         text,
  display_name     text,
  avatar_url       text,
  bio              text,
  note             text,
  shared_interests text[],
  match_score      numeric
)
language plpgsql
stable
security definer
set search_path=pg_catalog,public,pg_temp
as $$
declare
  me uuid := auth.uid();
begin
  if me is null then
    raise exception 'Authentication required' using errcode='28000';
  end if;

  return query
  select
    p.id,
    p.username,
    p.display_name,
    p.avatar_url,
    p.bio,
    ei.note,
    shared_interest_labels(me, p.id),
    person_friend_score(me, p.id)
  from public.event_interest ei
  join public.profiles p on p.id = ei.profile_id
  where social_private.discoverable(me) and social_private.discoverable(ei.profile_id)
    and exists(select 1 from public.event_interest own where own.meetup_id=meetup_id_in and own.profile_id=me)
    and exists(select 1 from public.meetups event where event.id=meetup_id_in and event.is_public and event.starts_at>statement_timestamp() and (event.host_id is null or event.host_id=me or public.safety_pair_allowed(me,event.host_id)))
    and ei.meetup_id = meetup_id_in
    and ei.profile_id <> me
    and p.is_active = true
    and ei.profile_id not in (
      select case when user_a = me then user_b else user_a end
      from public.connections where user_a = me or user_b = me
    )
    and ei.profile_id not in (select blocked_id from public.blocks where blocker_id = me)
    and ei.profile_id not in (select blocker_id from public.blocks where blocked_id = me)
  order by person_friend_score(me, p.id) desc;
end;
$$;

create or replace function public.get_recommended_meetups(max_results int default 10)
returns table (
  meetup_id     bigint,
  title         text,
  description   text,
  category      text,
  location_name text,
  starts_at     timestamptz,
  host_username text,
  similarity    numeric
)
language plpgsql
stable
security definer
set search_path=pg_catalog,public,pg_temp
as $$
declare
  me uuid := auth.uid();
begin
  if me is null then
    raise exception 'Authentication required' using errcode='28000';
  end if;

  if max_results is null or max_results not between 1 and 30 then raise exception 'Invalid recommendation limit' using errcode='22023'; end if;
  return query
  select
    m.id,
    m.title,
    m.description,
    m.category,
    m.location_name,
    m.starts_at,
    p.username,
    round((
      vec_similarity(user_interest_vector(me), meetup_embedding(m.id)) * 0.6
      + vec_similarity(profile_embedding(me), meetup_embedding(m.id)) * 0.4
    )::numeric, 4)
  from public.meetups m
  join public.profiles p on p.id = m.host_id
  where auth.uid() is not null and social_private.discoverable(auth.uid())
    and (m.host_id=auth.uid() or (social_private.discoverable(m.host_id) and public.safety_pair_allowed(auth.uid(),m.host_id)))
    and m.is_public = true
    and m.starts_at > now()
    and m.id not in (select meetup_id from public.meetup_attendees where profile_id = me)
  order by 8 desc, m.starts_at asc
  limit max_results;
end;
$$;

-- Existing group workers/proposals already recheck bilateral blocks. Extend
-- their profile eligibility, not group membership or post-match lifecycle.
do $$ declare definition text; begin
 if to_regprocedure('event_group_private.profile_valid(uuid)') is not null then
  definition:=pg_catalog.pg_get_functiondef('event_group_private.profile_valid(uuid)'::regprocedure);
  if position('where p.id=actor_in and p.is_active' in definition)=0 then raise exception 'Unreviewed group eligibility body' using errcode='22023'; end if;
  definition:=replace(definition,'where p.id=actor_in and p.is_active','where p.id=actor_in and p.is_active and social_private.discoverable(actor_in)');
  execute definition;
 end if;
end $$;
revoke all on function public.get_events_with_interest(text,text,integer),public.get_event_matches(bigint),public.get_recommended_meetups(integer) from public,anon,authenticated;
grant execute on function public.get_events_with_interest(text,text,integer),public.get_event_matches(bigint),public.get_recommended_meetups(integer) to authenticated;
do $$ declare signature text; begin
 foreach signature in array array['public.join_queue(text)','public.leave_queue()','public.express_event_interest(bigint,text)','public.withdraw_event_interest(bigint)','public.get_queue_status()','public.search_people(text,integer)','public.get_events_with_interest(text,text,integer)','public.get_event_matches(bigint)','public.get_recommended_meetups(integer)'] loop
  if has_function_privilege('anon',signature,'EXECUTE') or not has_function_privilege('authenticated',signature,'EXECUTE') then raise exception 'Discovery RPC privilege mismatch' using errcode='42501'; end if;
 end loop;
end $$;


-- docs/friends-search-preferences-migration.sql

set local lock_timeout = '3s';
set local statement_timeout = '30s';
do $$ begin
  if current_setting('server_encoding') <> 'UTF8'
    or to_regprocedure('public.profile_language_key(text)') is null
    or to_regclass('public.profiles') is null then
    raise exception 'Friends preference prerequisites missing' using errcode='22023';
  end if;
end $$;

create function public.valid_friends_search_preferences(prefs_in jsonb)
returns boolean language plpgsql immutable set search_path = '' as $$
declare item jsonb; area jsonb; label_in text; labels text[] := '{}'::text[];
begin
  if jsonb_typeof(prefs_in) is distinct from 'object' then return false; end if;
  if (select count(*) from jsonb_object_keys(prefs_in)) <> 5
    or not prefs_in ?& array['ageMin','ageMax','radiusMiles','goals','searchArea'] then return false; end if;
  if jsonb_typeof(prefs_in->'ageMin') is distinct from 'number'
    or jsonb_typeof(prefs_in->'ageMax') is distinct from 'number'
    or jsonb_typeof(prefs_in->'radiusMiles') is distinct from 'number' then return false; end if;
  if (prefs_in->>'ageMin')::numeric not between 18 and 99
    or (prefs_in->>'ageMax')::numeric not between 18 and 99
    or (prefs_in->>'radiusMiles')::numeric not between 1 and 100
    or trunc((prefs_in->>'ageMin')::numeric) <> (prefs_in->>'ageMin')::numeric
    or trunc((prefs_in->>'ageMax')::numeric) <> (prefs_in->>'ageMax')::numeric
    or trunc((prefs_in->>'radiusMiles')::numeric) <> (prefs_in->>'radiusMiles')::numeric
    or (prefs_in->>'ageMin')::numeric > (prefs_in->>'ageMax')::numeric then return false; end if;
  if jsonb_typeof(prefs_in->'goals') is distinct from 'array' then return false; end if;
  if jsonb_array_length(prefs_in->'goals') > 20 then return false; end if;
  for item in select value from jsonb_array_elements(prefs_in->'goals') loop
    if jsonb_typeof(item) is distinct from 'string' then return false; end if;
    label_in := item #>> '{}';
    if char_length(label_in) > 120 or (public.profile_language_key(label_in) collate "C") = ''
      or (label_in collate "C") = any(labels) then return false; end if;
    labels := array_append(labels,label_in);
  end loop;
  area := prefs_in->'searchArea';
  if jsonb_typeof(area) is distinct from 'object' then return false; end if;
  if not area ?& array['source','resolvedLocationRef'] then return false; end if;
  if jsonb_typeof(area->'source') is distinct from 'string'
    or (area->>'source' collate "C") not in ('home','temporary') then return false; end if;
  if (area->>'source' collate "C") = 'home' then
    if (select count(*) from jsonb_object_keys(area)) <> 2 then return false; end if;
  else
    if (select count(*) from jsonb_object_keys(area)) <> 3 or not area ? 'areaLabel' then return false; end if;
    if jsonb_typeof(area->'areaLabel') is distinct from 'string' then return false; end if;
    if char_length(area->>'areaLabel') > 120 or (public.profile_language_key(area->>'areaLabel') collate "C") = '' then return false; end if;
  end if;
  if jsonb_typeof(area->'resolvedLocationRef') not in ('string','null') then return false; end if;
  -- Pin the installed z.uuid() pattern, including its lowercase-only max UUID,
  -- plus exact length so trailing line terminators cannot pass an end anchor.
  if jsonb_typeof(area->'resolvedLocationRef') = 'string' then
    if char_length(area->>'resolvedLocationRef') <> 36 or (area->>'resolvedLocationRef' collate "C") !~ '^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$' then return false; end if;
  end if;
  return true;
end $$;
revoke all on function public.valid_friends_search_preferences(jsonb) from public, anon, authenticated;

-- Private, owner/source/label-bound resolution assertions, NOT a place catalogue.
-- There is deliberately no issuer RPC, seed/backfill, coordinate request payload,
-- expiry default or browser write grant. A future trusted resolver/parent owns
-- issuance/revocation; unresolved selections are still storable with a NULL ref.
create table public.friends_search_location_refs (
  id uuid primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  source text not null check ((source collate "C") in ('home','temporary')),
  area_label text not null check (char_length(area_label) <= 120 and (public.profile_language_key(area_label) collate "C") <> ''),
  latitude double precision not null check (latitude between -90 and 90),
  longitude double precision not null check (longitude between -180 and 180),
  usable boolean not null
);
alter table public.friends_search_location_refs enable row level security;
revoke all on public.friends_search_location_refs from public, anon, authenticated;

create table public.friends_search_preferences (
  user_id uuid primary key references auth.users(id) on delete cascade,
  revision bigint not null check (revision between 1 and 9007199254740991),
  preferences jsonb not null check (public.valid_friends_search_preferences(preferences))
);
alter table public.friends_search_preferences enable row level security;
revoke all on public.friends_search_preferences from public, anon, authenticated;
-- No browser SELECT/DML policies or grants on either private table. Review
-- effective/inherited/default table, column and function privileges before use.
-- Definitions fail on preexisting objects instead of adopting unknown ownership.

create function public.get_friends_search_preferences()
returns jsonb language plpgsql security definer set search_path = '' as $$
declare actor uuid := auth.uid(); result jsonb;
begin
  if actor is null then raise exception 'Authentication required' using errcode='28000'; end if;
  select jsonb_build_object('revision',p.revision,'preferences',p.preferences) into result
    from public.friends_search_preferences p where p.user_id = actor;
  return coalesce(result,'{"revision":0,"preferences":null}'::jsonb);
end $$;
revoke all on function public.get_friends_search_preferences() from public, anon, authenticated;
grant execute on function public.get_friends_search_preferences() to authenticated;

create function public.save_friends_search_preferences(preferences_in jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare actor uuid := auth.uid(); expected_revision bigint; prefs jsonb; area jsonb;
  reference_in uuid; resolved public.friends_search_location_refs%rowtype; home_label text;
begin
  if actor is null then raise exception 'Authentication required' using errcode='28000'; end if;
  if current_setting('transaction_isolation') <> 'read committed' then
    raise exception 'Friends preference writes require READ COMMITTED' using errcode='25001'; end if;
  if jsonb_typeof(preferences_in) is distinct from 'object' then
    raise exception 'Invalid Friends preferences' using errcode='22023'; end if;
  if (select count(*) from jsonb_object_keys(preferences_in)) <> 2
    or not preferences_in ?& array['expectedRevision','preferences']
    or jsonb_typeof(preferences_in->'expectedRevision') is distinct from 'number'
    or not public.valid_friends_search_preferences(preferences_in->'preferences') then
    raise exception 'Invalid Friends preferences' using errcode='22023'; end if;
  if (preferences_in->>'expectedRevision')::numeric < 0
    or (preferences_in->>'expectedRevision')::numeric >= 9007199254740991
    or trunc((preferences_in->>'expectedRevision')::numeric) <> (preferences_in->>'expectedRevision')::numeric then
    raise exception 'Invalid or exhausted revision' using errcode='22023'; end if;
  expected_revision := (preferences_in->>'expectedRevision')::numeric::bigint;
  prefs := preferences_in->'preferences'; area := prefs->'searchArea';
  reference_in := (area->>'resolvedLocationRef')::uuid;
  if reference_in is not null then
    -- Lock order: current home (when needed), trusted reference, preferences.
    -- Future trusted issuers must respect this order too. Never change home.
    if (area->>'source' collate "C") = 'home' then
      select p.location_city into home_label from public.profiles p where p.id = actor for share;
      if not found or home_label is null then
        raise exception 'Invalid location reference' using errcode='22023'; end if;
    end if;
    select r.* into resolved from public.friends_search_location_refs r
      where r.id = reference_in and r.user_id = actor and r.usable for share;
    if not found then raise exception 'Invalid location reference' using errcode='22023'; end if;
    if (resolved.source collate "C") <> (area->>'source' collate "C")
      or (resolved.area_label collate "C") is distinct from ((case when (area->>'source' collate "C") = 'home' then home_label else area->>'areaLabel' end) collate "C") then
      raise exception 'Invalid location reference' using errcode='22023'; end if;
  end if;
  if expected_revision = 0 then
    insert into public.friends_search_preferences(user_id,revision,preferences)
      values(actor,1,prefs) on conflict(user_id) do nothing;
  else
    update public.friends_search_preferences set preferences = prefs, revision = revision + 1
      where user_id = actor and revision = expected_revision;
  end if;
  if not found then raise exception 'Friends preferences revision conflict' using errcode='FP409'; end if;
  return public.get_friends_search_preferences();
end $$;
revoke all on function public.save_friends_search_preferences(jsonb) from public, anon, authenticated;
grant execute on function public.save_friends_search_preferences(jsonb) to authenticated;


-- docs/dating-aggregate-migration.sql

set local lock_timeout = '3s';
set local statement_timeout = '30s';
do $$ begin
  if current_setting('server_encoding') <> 'UTF8'
    or to_regprocedure('public.valid_friends_search_preferences(jsonb)') is null
    or to_regprocedure('public.profile_language_key(text)') is null
    or to_regclass('public.profiles') is null then
    raise exception 'Dating prerequisites missing' using errcode='22023'; end if;
  if not has_table_privilege(current_user,'public.profiles','SELECT')
    or (not exists(select 1 from pg_roles where rolname=current_user and (rolsuper or rolbypassrls))
      and not exists(select 1 from pg_class where oid='public.profiles'::regclass and pg_get_userbyid(relowner)=current_user and not relforcerowsecurity)) then
    raise exception 'Reviewed canonical DOB read owner required' using errcode='42501'; end if;
end $$;

create function public.dating_default_profile() returns jsonb language sql immutable set search_path='' as $$
  select '{"gender":"","sexuality":"","intent":"","style":"","heightInches":null,"visibility":{"gender":false,"sexuality":false,"height":false},"clarifiedTargets":[],"enabled":false}'::jsonb;
$$;
create function public.dating_clear_targets(p jsonb) returns jsonb language sql immutable set search_path='' as $$
  select case
    when (p->>'sexuality' collate "C")='Straight' and (p->>'gender' collate "C")='Man' then '["Woman"]'::jsonb
    when (p->>'sexuality' collate "C")='Straight' and (p->>'gender' collate "C")='Woman' then '["Man"]'::jsonb
    when (p->>'sexuality' collate "C")='Gay' and (p->>'gender' collate "C") in ('Man','Woman') then jsonb_build_array(p->>'gender')
    when (p->>'sexuality' collate "C")='Lesbian' and (p->>'gender' collate "C")='Woman' then '["Woman"]'::jsonb
    else null end;
$$;
create function public.dating_targets(p jsonb) returns jsonb language sql immutable set search_path='' as $$
  select case when p->>'gender'='' or p->>'sexuality'='' then null else
    coalesce(public.dating_clear_targets(p),nullif(p->'clarifiedTargets','[]'::jsonb)) end;
$$;
create function public.dating_complete(p jsonb) returns boolean language sql immutable set search_path='' as $$
  select coalesce(p->>'gender'<>'' and p->>'sexuality'<>'' and p->>'intent'<>'' and p->>'style'<>'' and public.dating_targets(p) is not null,false);
$$;
-- Target compatibility only; not consent, eligibility, safety or live admission.
create function public.dating_reciprocal_targets(a jsonb, b jsonb) returns boolean language sql immutable set search_path='' as $$
  select coalesce((public.dating_targets(a) ? (b->>'gender')) and (public.dating_targets(b) ? (a->>'gender')),false);
$$;
create function public.valid_dating_profile(p jsonb) returns boolean language plpgsql immutable set search_path='' as $$
declare k text; v jsonb; seen text[] := '{}'; label_in text;
begin
  if jsonb_typeof(p) is distinct from 'object' then return false; end if;
  if (select count(*) from jsonb_object_keys(p))<>8 or not p ?& array['gender','sexuality','intent','style','heightInches','visibility','clarifiedTargets','enabled'] then return false; end if;
  foreach k in array array['gender','sexuality','intent','style'] loop
    if jsonb_typeof(p->k) is distinct from 'string' then return false; end if;
    label_in:=p->>k;
    if char_length(label_in)>120 or (label_in<>'' and public.profile_language_key(label_in)='') then return false; end if;
  end loop;
  if (p->>'intent' collate "C") not in ('','Long-term relationship','Long-term, open to short','Short-term, open to long','Something casual','Still figuring it out')
    or (p->>'style' collate "C") not in ('','Monogamy','Non-monogamy','Exploring my relationship style') then return false; end if;
  if jsonb_typeof(p->'heightInches') is distinct from 'null' then
    if jsonb_typeof(p->'heightInches') is distinct from 'number' then return false; end if;
    if (p->>'heightInches')::numeric not between 24 and 107 or trunc((p->>'heightInches')::numeric)<>(p->>'heightInches')::numeric then return false; end if;
  end if;
  v:=p->'visibility';
  if jsonb_typeof(v) is distinct from 'object' then return false; end if;
  if (select count(*) from jsonb_object_keys(v))<>3 or not v ?& array['gender','sexuality','height']
    or exists(select 1 from jsonb_each(v) e where jsonb_typeof(e.value) is distinct from 'boolean') then return false; end if;
  if jsonb_typeof(p->'enabled') is distinct from 'boolean' or jsonb_typeof(p->'clarifiedTargets') is distinct from 'array' then return false; end if;
  if jsonb_array_length(p->'clarifiedTargets')>4 then return false; end if;
  for v in select value from jsonb_array_elements(p->'clarifiedTargets') loop
    if jsonb_typeof(v) is distinct from 'string' then return false; end if;
    label_in:=v #>> '{}';
    if char_length(label_in)>120 or public.profile_language_key(label_in)='' or (label_in collate "C")=any(seen) then return false; end if;
    seen:=array_append(seen,label_in);
  end loop;
  if cardinality(seen)>0 and (p->>'gender'='' or p->>'sexuality'='' or public.dating_clear_targets(p) is not null) then return false; end if;
  return not (p->>'enabled')::boolean or public.dating_complete(p);
end $$;
create function public.valid_dating_search(s jsonb) returns boolean language plpgsql immutable set search_path='' as $$
begin
  if s='null'::jsonb then return true; end if;
  if jsonb_typeof(s) is distinct from 'object' then return false; end if;
  if (select count(*) from jsonb_object_keys(s))<>4 or not s ?& array['ageMin','ageMax','radiusMiles','searchArea'] then return false; end if;
  return public.valid_friends_search_preferences(s || '{"goals":[]}'::jsonb);
end $$;
-- STABLE rather than IMMUTABLE: named-zone interpretation uses timezone data.
create function public.dating_campus_date(instant_in timestamptz) returns date language sql stable set search_path='' as $$
  select (instant_in at time zone 'America/New_York')::date;
$$;
create function public.dating_adult_on(dob date, as_of date) returns boolean language plpgsql immutable set search_path='' as $$
begin
  if dob is null or as_of is null or not isfinite(dob) or not isfinite(as_of) then return false; end if;
  if dob not between date '0001-01-01' and date '9999-12-31' or as_of not between date '0001-01-01' and date '9999-12-31' or dob>as_of then return false; end if;
  return extract(year from as_of)-extract(year from dob)
    - case when to_char(as_of,'MMDD') < to_char(dob,'MMDD') then 1 else 0 end >= 18;
end $$;

-- No issuer, browser writes, automatic resolution or fictional coordinates.
-- A later trusted resolver must bind the exact current owner/source/area label.
create table public.dating_search_location_refs (
  id uuid primary key, user_id uuid not null references auth.users(id) on delete cascade,
  source text not null check ((source collate "C") in ('home','temporary')),
  area_label text not null check (char_length(area_label)<=120 and public.profile_language_key(area_label)<>''),
  latitude double precision not null check (latitude between -90 and 90),
  longitude double precision not null check (longitude between -180 and 180), usable boolean not null
);
alter table public.dating_search_location_refs enable row level security;
revoke all on public.dating_search_location_refs from public, anon, authenticated;
create table public.dating_owner_aggregates (
  user_id uuid primary key references auth.users(id) on delete cascade,
  profile_revision bigint not null check (profile_revision between 1 and 9007199254740991),
  search_revision bigint not null check (search_revision between 1 and 9007199254740991),
  profile jsonb not null check (public.valid_dating_profile(profile)),
  search jsonb not null check (public.valid_dating_search(search)),
  check (not (profile->>'enabled')::boolean or search->'searchArea'->>'resolvedLocationRef' is not null)
);
alter table public.dating_owner_aggregates enable row level security;
revoke all on public.dating_owner_aggregates from public, anon, authenticated;

create function public.dating_location_resolved(actor uuid, s jsonb, home text) returns boolean language sql stable set search_path='' as $$
  select exists(select 1 from public.dating_search_location_refs r where r.id=(s->'searchArea'->>'resolvedLocationRef')::uuid
    and r.user_id=actor and r.usable and (r.source collate "C")=(s->'searchArea'->>'source' collate "C")
    and (r.area_label collate "C")=(case when s->'searchArea'->>'source'='home' then home else s->'searchArea'->>'areaLabel' end collate "C"));
$$;
create function public.get_dating_preferences() returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=auth.uid(); as_of date:=public.dating_campus_date(transaction_timestamp()); result jsonb;
begin
  if actor is null then raise exception 'Authentication required' using errcode='28000'; end if;
  -- One statement snapshot for stored data, canonical DOB/home and trusted ref.
  select jsonb_build_object('profileRevision',coalesce(d.profile_revision,0),'searchRevision',coalesce(d.search_revision,0),
    'profile',v.p,'search',v.s,'eligibility',jsonb_build_object('asOf',to_char(as_of,'YYYY-MM-DD'),'adult',v.adult,'locationResolved',v.resolved),
    'effectiveEnabled',(v.p->>'enabled')::boolean and public.dating_complete(v.p) and v.adult and v.resolved) into result
  from (values(actor)) me(id)
  left join public.dating_owner_aggregates d on d.user_id=me.id
  left join public.profiles p on p.id=me.id
  cross join lateral(select coalesce(d.profile,public.dating_default_profile()) p,coalesce(d.search,'null'::jsonb) s,
    public.dating_adult_on(p.birthdate,as_of) adult,public.dating_location_resolved(actor,d.search,p.location_city) resolved) v;
  return result;
end $$;

create function public.save_dating_preferences(aggregate_in jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=auth.uid(); ep bigint; es bigint; k text; n numeric; p jsonb; s jsonb;
  previous public.dating_owner_aggregates%rowtype; dob date; home text;
  ref public.dating_search_location_refs%rowtype; as_of date:=public.dating_campus_date(transaction_timestamp());
begin
  if actor is null then raise exception 'Authentication required' using errcode='28000'; end if;
  if current_setting('transaction_isolation')<>'read committed' then raise exception 'READ COMMITTED required' using errcode='25001'; end if;
  if jsonb_typeof(aggregate_in) is distinct from 'object' then raise exception 'Invalid Dating aggregate' using errcode='22023'; end if;
  if (select count(*) from jsonb_object_keys(aggregate_in))<>4 or not aggregate_in ?& array['expectedProfileRevision','expectedSearchRevision','profile','search'] then raise exception 'Invalid Dating aggregate' using errcode='22023'; end if;
  foreach k in array array['expectedProfileRevision','expectedSearchRevision'] loop
    if jsonb_typeof(aggregate_in->k) is distinct from 'number' then raise exception 'Invalid revision' using errcode='22023'; end if;
    n:=(aggregate_in->>k)::numeric;
    if n<0 or n>=9007199254740991 or trunc(n)<>n then raise exception 'Invalid revision' using errcode='22023'; end if;
  end loop;
  ep:=(aggregate_in->>'expectedProfileRevision')::numeric::bigint; es:=(aggregate_in->>'expectedSearchRevision')::numeric::bigint;
  p:=aggregate_in->'profile'; s:=aggregate_in->'search';
  if not public.valid_dating_profile(p) or not public.valid_dating_search(s) then raise exception 'Invalid Dating values' using errcode='22023'; end if;
  -- Lock order: canonical profile (DOB/home), selected trusted ref, aggregate.
  -- No profile/home/DOB updates; later issuers must use the same order.
  select u.birthdate,u.location_city into dob,home from public.profiles u where u.id=actor for share;
  if s->'searchArea'->>'resolvedLocationRef' is not null then
    select r.* into ref from public.dating_search_location_refs r where r.id=(s->'searchArea'->>'resolvedLocationRef')::uuid and r.user_id=actor for share;
    if not found or not public.dating_location_resolved(actor,s,home) then raise exception 'Invalid Dating location reference' using errcode='22023'; end if;
  end if;
  if (p->>'enabled')::boolean and (not public.dating_adult_on(dob,as_of) or s->'searchArea'->>'resolvedLocationRef' is null) then raise exception 'Dating eligibility incomplete' using errcode='22023'; end if;
  select d.* into previous from public.dating_owner_aggregates d where d.user_id=actor for update;
  if coalesce(previous.profile_revision,0)<>ep or coalesce(previous.search_revision,0)<>es then raise exception 'Dating aggregate revision conflict' using errcode='DA409'; end if;
  -- A missing aggregate or two unset labels has no prior identity/targets to
  -- invalidate. Any partial prior identity keeps the existing edit guard.
  if previous.user_id is not null
    and ((previous.profile->>'gender' collate "C")<>'' or (previous.profile->>'sexuality' collate "C")<>'')
    and ((coalesce(previous.profile,public.dating_default_profile())->>'gender' collate "C") is distinct from (p->>'gender' collate "C")
      or (coalesce(previous.profile,public.dating_default_profile())->>'sexuality' collate "C") is distinct from (p->>'sexuality' collate "C")) and p->'clarifiedTargets'<>'[]'::jsonb then
    raise exception 'Identity edit must clear clarification; save identity draft first' using errcode='22023'; end if;
  if previous.user_id is null then
    insert into public.dating_owner_aggregates(user_id,profile_revision,search_revision,profile,search) values(actor,1,1,p,s) on conflict(user_id) do nothing;
    if not found then raise exception 'Dating aggregate revision conflict' using errcode='DA409'; end if;
  else
    update public.dating_owner_aggregates set profile_revision=profile_revision+1,search_revision=search_revision+1,profile=p,search=s where user_id=actor;
  end if;
  return public.get_dating_preferences();
end $$;

-- Explicit helper/RPC ACLs; no anonymous execute or direct browser table access.
revoke all on function public.dating_default_profile(),public.dating_clear_targets(jsonb),public.dating_targets(jsonb),public.dating_complete(jsonb),public.dating_reciprocal_targets(jsonb,jsonb),public.valid_dating_profile(jsonb),public.valid_dating_search(jsonb),public.dating_campus_date(timestamptz),public.dating_adult_on(date,date),public.dating_location_resolved(uuid,jsonb,text),public.get_dating_preferences(),public.save_dating_preferences(jsonb) from public, anon, authenticated;
grant execute on function public.get_dating_preferences(),public.save_dating_preferences(jsonb) to authenticated;


-- docs/search-location-migration.sql

set local lock_timeout='3s';
set local statement_timeout='30s';
do $$ begin
 if to_regclass('public.friends_search_location_refs') is null or to_regclass('public.dating_search_location_refs') is null
 or to_regclass('public.account_settings') is null or to_regprocedure('public.profile_language_key(text)') is null then raise exception 'Location prerequisites missing' using errcode='22023'; end if;
 if not exists(select 1 from pg_catalog.pg_proc where oid='public.dating_location_resolved(uuid,jsonb,text)'::regprocedure and pg_get_userbyid(proowner)=current_user) then raise exception 'Location helper owner mismatch' using errcode='42501';end if;
 if exists(select 1 from pg_catalog.pg_roles where rolname='pebble_location_catalog_publisher') then raise exception 'Publisher role requires fresh reviewed ownership' using errcode='42501'; end if;
end $$;
create role pebble_location_catalog_publisher nologin nosuperuser nobypassrls nocreatedb nocreaterole;
create schema location_private;
revoke all on schema location_private from public,anon,authenticated,pebble_location_catalog_publisher;
create table location_private.places (
 id uuid primary key,
 label text not null check(char_length(label) between 1 and 120 and public.profile_language_key(label)<>''),
 region text not null check(char_length(region)<=120),
 aliases text[] not null check(cardinality(aliases) between 1 and 20 and array_position(aliases,null) is null),
 latitude double precision not null check(latitude between -90 and 90),
 longitude double precision not null check(longitude between -180 and 180),
 provenance text not null check(char_length(provenance) between 1 and 250),
 verified_until timestamptz not null check(isfinite(verified_until)), enabled boolean not null
);
create table location_private.assertions (
 mode text not null check(mode in('friends','dating')), id uuid not null,
 actor_id uuid not null references auth.users(id) on delete cascade,
 method text not null check(method in('geocoded-area','device-reported')),
 issued_at timestamptz not null, expires_at timestamptz not null check(isfinite(issued_at) and isfinite(expires_at) and expires_at>issued_at),
 place_id uuid references location_private.places(id), accuracy_meters double precision,
 primary key(mode,id),
 check((method='geocoded-area' and place_id is not null and accuracy_meters is null) or (method='device-reported' and place_id is null and accuracy_meters is not null and accuracy_meters between 0.000001 and 1000))
);
create table location_private.requests (
 actor_id uuid not null references auth.users(id) on delete cascade,
 request_id uuid not null, fingerprint bytea not null,
 mode text not null, reference_id uuid not null,
 created_at timestamptz not null default statement_timestamp(),
 primary key(actor_id,request_id),foreign key(mode,reference_id) references location_private.assertions(mode,id)
);
alter table location_private.places enable row level security;
alter table location_private.assertions enable row level security;
alter table location_private.requests enable row level security;
revoke all on all tables in schema location_private from public,anon,authenticated,pebble_location_catalog_publisher;

create function location_private.valid_uuid(value text) returns boolean language sql immutable set search_path='' as $$
 select coalesce(char_length(value)=36 and value ~ '^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$',false);
$$;
create function location_private.usable(mode_in text,reference_in uuid,actor_in uuid,source_in text,label_in text) returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from location_private.assertions proof join (
  select 'friends' mode,r.* from public.friends_search_location_refs r union all select 'dating' mode,r.* from public.dating_search_location_refs r
 ) r on r.mode=proof.mode and r.id=proof.id left join location_private.places place on place.id=proof.place_id
 where proof.mode=mode_in and proof.id=reference_in and proof.actor_id=actor_in and r.user_id=actor_in and r.usable
 and r.source=source_in and r.area_label=label_in and proof.issued_at<=statement_timestamp() and proof.expires_at>statement_timestamp()
 and ((proof.method='device-reported' and source_in='temporary' and exists(select 1 from public.account_settings settings where settings.user_id=actor_in and public.detailed_settings_masters(settings.settings) is not null and settings.settings->'location'='true'::jsonb)) or (place.enabled and place.verified_until>statement_timestamp() and r.latitude=place.latitude and r.longitude=place.longitude
 and (source_in<>'temporary' or r.area_label=place.label)
 and (source_in<>'home' or exists(select 1 from unnest(place.aliases) alias where public.profile_language_key(alias)=public.profile_language_key(label_in))))));
$$;
create function public.get_search_location_receipt(mode_in text,reference_in uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare actor uuid:=safety_private.actor(); result jsonb; begin
 if mode_in is null or mode_in not in('friends','dating') or reference_in is null then raise exception 'Invalid receipt' using errcode='22023'; end if;
 select jsonb_build_object('id',r.id,'mode',r.mode,'source',r.source,'areaLabel',r.area_label,'method',proof.method,
 'expiresAt',to_char(proof.expires_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
 'usable',location_private.usable(r.mode,r.id,actor,r.source,case when r.source='home' then p.location_city else r.area_label end)) into result
 from location_private.assertions proof join (
  select 'friends' mode,r.* from public.friends_search_location_refs r union all select 'dating' mode,r.* from public.dating_search_location_refs r
 ) r on r.mode=proof.mode and r.id=proof.id left join public.profiles p on p.id=actor
 where proof.actor_id=actor and proof.mode=mode_in and proof.id=reference_in;
 if result is null then raise exception 'Location receipt unavailable' using errcode='PT404'; end if;
 return result;
end $$;
create function public.search_location_places(query_in text) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare actor uuid:=safety_private.actor(); result jsonb;begin
 if query_in is null or char_length(query_in) not between 1 and 120 or public.profile_language_key(query_in)='' then raise exception 'Invalid place query' using errcode='22023'; end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'label',label,'region',region) order by label,id),'[]') into result from (
  select p.id,p.label,p.region from location_private.places p where p.enabled and p.verified_until>statement_timestamp()
  and (p.label ilike '%'||query_in||'%' or exists(select 1 from unnest(p.aliases) alias where alias ilike '%'||query_in||'%')) order by p.label,p.id limit 10
 ) matches;
 return jsonb_build_object('places',result);
end $$;
create function location_private.replay(request_in uuid,payload_in jsonb,actor uuid) returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare prior location_private.requests;begin
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'READ COMMITTED required' using errcode='25001'; end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('pebble.location.owner.v1:'||actor::text,0));
 select * into prior from location_private.requests where actor_id=actor and request_id=request_in;
 if found then
  if prior.fingerprint<>pg_catalog.sha256(pg_catalog.convert_to(payload_in::text,'UTF8')) then raise exception 'Location request conflict' using errcode='LC409'; end if;
  return public.get_search_location_receipt(prior.mode,prior.reference_id);
 end if;
 if (select count(*) from location_private.requests where actor_id=actor and created_at>statement_timestamp()-interval '1 hour')>=10
 or (select count(*) from location_private.requests where actor_id=actor and created_at>statement_timestamp()-interval '24 hours')>=50 then raise exception 'Location issuance limit' using errcode='LC429'; end if;
 return null;
end $$;
create function location_private.issue(actor uuid,request_in uuid,payload jsonb,mode_in text,source_in text,label_in text,lat double precision,lon double precision,method_in text,expiry timestamptz,place uuid,accuracy double precision) returns jsonb language plpgsql security definer set search_path='' as $$
declare reference_in uuid:=gen_random_uuid();begin
 if mode_in='friends' then insert into public.friends_search_location_refs(id,user_id,source,area_label,latitude,longitude,usable) values(reference_in,actor,source_in,label_in,lat,lon,true);
 else insert into public.dating_search_location_refs(id,user_id,source,area_label,latitude,longitude,usable) values(reference_in,actor,source_in,label_in,lat,lon,true); end if;
 insert into location_private.assertions(mode,id,actor_id,method,issued_at,expires_at,place_id,accuracy_meters) values(mode_in,reference_in,actor,method_in,statement_timestamp(),expiry,place,accuracy);
 insert into location_private.requests(actor_id,request_id,fingerprint,mode,reference_id) values(actor,request_in,pg_catalog.sha256(pg_catalog.convert_to(payload::text,'UTF8')),mode_in,reference_in);
 return public.get_search_location_receipt(mode_in,reference_in);
end $$;
create function public.resolve_search_area(resolution_in jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=safety_private.actor(); place location_private.places;mode_in text;source_in text;label_in text;request_in uuid;prior jsonb;begin
 if jsonb_typeof(resolution_in) is distinct from 'object' or (select count(*) from jsonb_object_keys(resolution_in))<>4 or not resolution_in ?& array['requestId','mode','source','placeId']
 or jsonb_typeof(resolution_in->'requestId')<>'string' or jsonb_typeof(resolution_in->'placeId')<>'string'
 or jsonb_typeof(resolution_in->'mode')<>'string' or jsonb_typeof(resolution_in->'source')<>'string' or resolution_in->>'mode' not in('friends','dating') or resolution_in->>'source' not in('home','temporary') then raise exception 'Invalid resolution' using errcode='22023'; end if;
 if not location_private.valid_uuid(resolution_in->>'requestId') or not location_private.valid_uuid(resolution_in->>'placeId') then raise exception 'Invalid location IDs' using errcode='22023';end if;
 begin request_in:=(resolution_in->>'requestId')::uuid;exception when invalid_text_representation then raise exception 'Invalid request' using errcode='22023';end;
 mode_in:=resolution_in->>'mode';source_in:=resolution_in->>'source';
 -- Match canonical home lock ordering: home -> assertion -> preference CAS.
 if source_in='home' then select location_city into label_in from public.profiles where id=actor for share; end if;
 prior:=location_private.replay(request_in,resolution_in,actor);if prior is not null then return prior;end if;
 begin select * into place from location_private.places where id=(resolution_in->>'placeId')::uuid and enabled and verified_until>statement_timestamp() for share;
 exception when invalid_text_representation then raise exception 'Invalid place' using errcode='22023';end;
 if not found then raise exception 'Place unavailable' using errcode='LC409';end if;
 if source_in='home' then
  if label_in is null or not exists(select 1 from unnest(place.aliases) alias where public.profile_language_key(alias)=public.profile_language_key(label_in)) then raise exception 'Home binding changed' using errcode='LC409';end if;
 else label_in:=place.label;end if;
 return location_private.issue(actor,request_in,resolution_in,mode_in,source_in,label_in,place.latitude,place.longitude,'geocoded-area',least(place.verified_until,statement_timestamp()+interval '30 days'),place.id,null);
end $$;
create function public.issue_browser_search_location(location_in jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=safety_private.actor();mode_in text;request_in uuid;lat double precision;lon double precision;accuracy double precision;observed timestamptz;prior jsonb;begin
 if jsonb_typeof(location_in) is distinct from 'object' or (select count(*) from jsonb_object_keys(location_in))<>7 or not location_in ?& array['requestId','mode','latitude','longitude','accuracyMeters','observedAt','consent'] then raise exception 'Invalid device location' using errcode='22023';end if;
 if jsonb_typeof(location_in->'requestId')<>'string' or jsonb_typeof(location_in->'mode')<>'string' or location_in->>'mode' not in('friends','dating')
 or location_in->'consent' is distinct from 'true'::jsonb or jsonb_typeof(location_in->'latitude')<>'number' or jsonb_typeof(location_in->'longitude')<>'number' or jsonb_typeof(location_in->'accuracyMeters')<>'number' or jsonb_typeof(location_in->'observedAt')<>'string' then raise exception 'Invalid device evidence' using errcode='22023';end if;
 if not location_private.valid_uuid(location_in->>'requestId') or char_length(location_in->>'observedAt')>40 or (location_in->>'observedAt') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T([01][0-9]|2[0-3]):[0-5][0-9](:[0-5][0-9](\.[0-9]+)?)?(Z|[+-][0-9]{2}:[0-9]{2})$' then raise exception 'Invalid location identity or timestamp' using errcode='22023';end if;
 begin request_in:=(location_in->>'requestId')::uuid;lat:=(location_in->>'latitude')::double precision;lon:=(location_in->>'longitude')::double precision;accuracy:=(location_in->>'accuracyMeters')::double precision;observed:=(location_in->>'observedAt')::timestamptz;
 exception when invalid_text_representation or invalid_datetime_format or datetime_field_overflow or numeric_value_out_of_range then raise exception 'Invalid device evidence' using errcode='22023';end;
 mode_in:=location_in->>'mode';
 if not(lat between -90 and 90 and lon between -180 and 180 and accuracy>0 and accuracy<=1000) or not isfinite(observed) then raise exception 'Invalid coordinates' using errcode='22023';end if;
 if not exists(select 1 from public.account_settings s where s.user_id=actor and public.detailed_settings_masters(s.settings) is not null and s.settings->'location'='true'::jsonb for share) then raise exception 'Device location opt-in required' using errcode='LC403';end if;
 prior:=location_private.replay(request_in,location_in,actor);if prior is not null then return prior;end if;
 if observed<statement_timestamp()-interval '5 minutes' or observed>statement_timestamp()+interval '15 seconds' then raise exception 'Device reading is stale' using errcode='22023';end if;
 return location_private.issue(actor,request_in,location_in,mode_in,'temporary','Current approximate location',lat,lon,'device-reported',statement_timestamp()+interval '1 hour',null,accuracy);
end $$;
-- Only a separately approved catalogue publisher can load reviewed global places.
-- It cannot read/write profiles, owner settings or location assertions.
create function public.publish_search_location_place(place_in jsonb) returns void language plpgsql security definer set search_path='' as $$
declare alias text;begin
 if current_setting('role')<>'pebble_location_catalog_publisher' then raise exception 'Catalogue publisher required' using errcode='42501';end if;
 if jsonb_typeof(place_in) is distinct from 'object' or (select count(*) from jsonb_object_keys(place_in))<>9 or not place_in ?& array['id','label','region','aliases','latitude','longitude','provenance','verifiedUntil','enabled'] then raise exception 'Invalid catalogue place' using errcode='22023';end if;
 if jsonb_typeof(place_in->'aliases')<>'array' or jsonb_array_length(place_in->'aliases') not between 1 and 20 or exists(select 1 from jsonb_array_elements(place_in->'aliases') x where jsonb_typeof(x)<>'string' or char_length(x #>> '{}') not between 1 and 120 or public.profile_language_key(x #>> '{}')='') then raise exception 'Invalid place aliases' using errcode='22023';end if;
 if exists(select 1 from jsonb_each(place_in) x where (x.key in('id','label','region','provenance','verifiedUntil') and jsonb_typeof(x.value)<>'string') or (x.key in('latitude','longitude') and jsonb_typeof(x.value)<>'number') or (x.key='enabled' and jsonb_typeof(x.value)<>'boolean')) then raise exception 'Invalid catalogue types' using errcode='22023';end if;
 insert into location_private.places(id,label,region,aliases,latitude,longitude,provenance,verified_until,enabled) values((place_in->>'id')::uuid,place_in->>'label',place_in->>'region',array(select jsonb_array_elements_text(place_in->'aliases')),(place_in->>'latitude')::double precision,(place_in->>'longitude')::double precision,place_in->>'provenance',(place_in->>'verifiedUntil')::timestamptz,(place_in->>'enabled')::boolean)
 on conflict(id) do update set label=excluded.label,region=excluded.region,aliases=excluded.aliases,latitude=excluded.latitude,longitude=excluded.longitude,provenance=excluded.provenance,verified_until=excluded.verified_until,enabled=excluded.enabled;
end $$;
-- Direct preferences cannot save expired/revoked/unproven or other-owner refs.
create function location_private.preference_guard() returns trigger language plpgsql security definer set search_path='' as $$
declare search jsonb;mode_in text;label_in text;begin
 if tg_table_name='friends_search_preferences' then search:=new.preferences;mode_in:='friends';else search:=new.search;mode_in:='dating';end if;
 if search->'searchArea'->>'resolvedLocationRef' is null then return new;end if;
 if search->'searchArea'->>'source'='home' then select location_city into label_in from public.profiles where id=new.user_id for share;else label_in:=search->'searchArea'->>'areaLabel';end if;
 if not location_private.usable(mode_in,(search->'searchArea'->>'resolvedLocationRef')::uuid,new.user_id,search->'searchArea'->>'source',label_in) then raise exception 'Search location unavailable' using errcode='LC409';end if;
 return new;
end $$;
create trigger friends_location_proof before insert or update on public.friends_search_preferences for each row execute function location_private.preference_guard();
create trigger dating_location_proof before insert or update on public.dating_owner_aggregates for each row execute function location_private.preference_guard();
create or replace function public.dating_location_resolved(actor uuid,s jsonb,home text) returns boolean language sql stable set search_path='' as $$
 select location_private.usable('dating',(s->'searchArea'->>'resolvedLocationRef')::uuid,actor,s->'searchArea'->>'source',case when s->'searchArea'->>'source'='home' then home else s->'searchArea'->>'areaLabel' end);
$$;
revoke all on all functions in schema location_private from public,anon,authenticated,pebble_location_catalog_publisher;
revoke all on function public.publish_search_location_place(jsonb),public.search_location_places(text),public.resolve_search_area(jsonb),public.issue_browser_search_location(jsonb),public.get_search_location_receipt(text,uuid) from public,anon,authenticated,pebble_location_catalog_publisher;
grant execute on function public.publish_search_location_place(jsonb) to pebble_location_catalog_publisher;
grant execute on function public.search_location_places(text),public.resolve_search_area(jsonb),public.issue_browser_search_location(jsonb),public.get_search_location_receipt(text,uuid) to authenticated;
do $$ declare role_in text;t text;f record;signature text;begin
 foreach role_in in array array['anon','authenticated','pebble_location_catalog_publisher'] loop
  if has_schema_privilege(role_in::name,'location_private','USAGE') then raise exception 'Inherited location schema bypass' using errcode='42501';end if;
  foreach t in array array['places','assertions','requests'] loop
   if has_table_privilege(role_in::name,'location_private.'||t,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') or has_any_column_privilege(role_in::name,'location_private.'||t,'SELECT,INSERT,UPDATE,REFERENCES') then raise exception 'Inherited location data bypass' using errcode='42501';end if;
  end loop;
  for f in select p.oid from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid=p.pronamespace where n.nspname='location_private' loop
   if has_function_privilege(role_in::name,f.oid,'EXECUTE') then raise exception 'Inherited location helper bypass' using errcode='42501';end if;
  end loop;
 end loop;
 if has_function_privilege('anon','public.publish_search_location_place(jsonb)','EXECUTE') or has_function_privilege('authenticated','public.publish_search_location_place(jsonb)','EXECUTE') then raise exception 'Public catalogue mutation bypass' using errcode='42501';end if;
 foreach signature in array array['public.search_location_places(text)','public.resolve_search_area(jsonb)','public.issue_browser_search_location(jsonb)','public.get_search_location_receipt(text,uuid)'] loop
  if has_function_privilege('anon',signature,'EXECUTE') or has_function_privilege('pebble_location_catalog_publisher',signature,'EXECUTE') or not has_function_privilege('authenticated',signature,'EXECUTE') then raise exception 'Location RPC privilege mismatch' using errcode='42501';end if;
 end loop;
end $$;


-- docs/active-nearby-migration.sql

set local lock_timeout='3s';set local statement_timeout='30s';
do $$ begin
 if to_regprocedure('location_private.usable(text,uuid,uuid,text,text)') is null or to_regprocedure('social_private.friends_discoverable(uuid)') is null
 or to_regprocedure('public.get_queue_match()') is null then raise exception 'Active matcher prerequisites missing' using errcode='22023';end if;
 if not exists(select 1 from pg_proc where oid='public.get_queue_match()'::regprocedure and pg_get_userbyid(proowner)=current_user) then raise exception 'Queue reader owner mismatch' using errcode='42501';end if;
end $$;
create schema active_private;
revoke all on schema active_private from public,anon,authenticated;
-- Only trusted current facts enter this internal relation. No raw browser input.
create function active_private.people() returns table(person uuid,username text,display_name text,avatar text,bio text,birthdate date,minimum_age integer,maximum_age integer,radius integer,reference uuid,latitude double precision,longitude double precision)
language sql stable security definer set search_path='' as $$
 select p.id,p.username,p.display_name,p.avatar_url,p.bio,p.birthdate,(f.preferences->>'ageMin')::integer,(f.preferences->>'ageMax')::integer,(f.preferences->>'radiusMiles')::integer,r.id,r.latitude,r.longitude
 from public.profiles p join auth.users u on u.id=p.id join public.friends_search_preferences f on f.user_id=p.id
 join public.friends_search_location_refs r on r.id=(f.preferences->'searchArea'->>'resolvedLocationRef')::uuid and r.user_id=p.id
 where social_private.friends_discoverable(p.id) and public.valid_friends_search_preferences(f.preferences)
 and location_private.usable('friends',r.id,p.id,f.preferences->'searchArea'->>'source',case when f.preferences->'searchArea'->>'source'='home' then p.location_city else f.preferences->'searchArea'->>'areaLabel' end);
$$;
create function active_private.ranking(actor uuid) returns table(person uuid,distance_miles double precision,interest_labels text[],overlap_seconds numeric)
language sql stable security definer set search_path='' as $$
 with pool as materialized(select p.* from active_private.people() p join public.queue_entries q on q.profile_id=p.person and q.queue_type='matchmaking'),
 pairs as(select other.*,mine.minimum_age mine_min,mine.maximum_age mine_max,mine.radius mine_radius,mine.birthdate mine_dob,
  2*(6371.0088/1.609344)*asin(sqrt(least(1::double precision,greatest(0::double precision,
   power(sin(radians(other.latitude-mine.latitude)/2),2)+cos(radians(mine.latitude))*cos(radians(other.latitude))*power(sin(radians(other.longitude-mine.longitude)/2),2))))) distance
 from pool mine cross join pool other where mine.person=actor and other.person<>actor and public.safety_pair_allowed(actor,other.person)),
 eligible as(select * from pairs where
  extract(year from age((statement_timestamp() at time zone 'America/New_York')::date,birthdate)) between mine_min and mine_max
  and extract(year from age((statement_timestamp() at time zone 'America/New_York')::date,mine_dob)) between minimum_age and maximum_age
  and distance<=least(radius,mine_radius)+8*2.220446049250313e-16*greatest(1::double precision,distance,least(radius,mine_radius)))
 select e.person,e.distance,
  coalesce((select array_agg(label order by comparison collate "C") from (
   select public.profile_language_key(a.text) comparison,min(a.text collate "C") label from public.user_interests a
   where a.profile_id=actor and exists(select 1 from public.user_interests b where b.profile_id=e.person and public.profile_language_key(b.text)=public.profile_language_key(a.text)) group by public.profile_language_key(a.text)
  ) shared),'{}'::text[]),
  coalesce((select sum(greatest(0,extract(epoch from(least(a.end_time,b.end_time)-greatest(a.start_time,b.start_time))))) from public.availability a join public.availability b on b.profile_id=e.person and b.dow=a.dow where a.profile_id=actor),0)
 from eligible e;
$$;
-- Preserve legacy wire signature, expose only the permitted single candidate.
create or replace function public.get_queue_match() returns table(
 queue_kind text,match_profile_id uuid,match_username text,match_display_name text,match_avatar_url text,match_bio text,match_score numeric,
 shared_interests text[],overlap_minutes integer,shared_windows jsonb,event_id bigint,event_title text,event_description text,event_category text,event_location text,event_starts_at timestamptz,event_host_id uuid)
language plpgsql volatile security definer set search_path='' as $$
declare actor uuid:=safety_private.actor();selected uuid;current_row record;profile_row record;kind text;begin
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'READ COMMITTED required' using errcode='25001';end if;
 select q.queue_type into kind from public.queue_entries q where q.profile_id=actor;
 if kind is null then raise exception 'Join a queue before checking' using errcode='AQ409';end if;
 if kind<>'matchmaking' then raise exception 'Downtime results await lifecycle approval' using errcode='AQ503';end if;
 if not exists(select 1 from active_private.people() p where p.person=actor) then raise exception 'Choose current Friends filters and location' using errcode='AQ409';end if;
 select r.person into selected from active_private.ranking(actor) r order by r.distance_miles,cardinality(r.interest_labels) desc,r.overlap_seconds desc,r.person limit 1;
 if selected is null then return;end if;
 -- Same pair fence as block/contact. Recheck with a new READ COMMITTED snapshot
 -- after waiting; an old snapshot cannot authorize a blocked/cancelled candidate.
 perform social_private.lock_pair(actor,selected);
 perform 1 from public.account_settings s where s.user_id in(actor,selected) order by s.user_id for share;
 perform 1 from public.detailed_settings s where s.user_id in(actor,selected) order by s.user_id for share;
 perform 1 from public.queue_entries q where q.profile_id in(actor,selected) order by q.profile_id for share;
 perform 1 from public.friends_search_location_refs r join public.friends_search_preferences f on f.user_id=r.user_id and r.id=(f.preferences->'searchArea'->>'resolvedLocationRef')::uuid where f.user_id in(actor,selected) order by r.id for share of r;
 perform 1 from location_private.assertions a join public.friends_search_preferences f on f.user_id=a.actor_id and a.id=(f.preferences->'searchArea'->>'resolvedLocationRef')::uuid where a.mode='friends' and f.user_id in(actor,selected) order by a.id for share of a;
 perform 1 from location_private.places p join location_private.assertions a on a.place_id=p.id join public.friends_search_preferences f on f.user_id=a.actor_id and a.id=(f.preferences->'searchArea'->>'resolvedLocationRef')::uuid where a.mode='friends' and f.user_id in(actor,selected) order by p.id for share of p;
 perform 1 from public.friends_search_preferences f where f.user_id in(actor,selected) order by f.user_id for share;
 select * into current_row from active_private.ranking(actor) r where r.person=selected;
 if not found then return;end if;
 select * into profile_row from active_private.people() p where p.person=selected;
 if not found then return;end if;
 return query select 'matchmaking'::text,selected,profile_row.username,profile_row.display_name,profile_row.avatar,profile_row.bio,null::numeric,
 current_row.interest_labels,floor(current_row.overlap_seconds/60)::integer,null::jsonb,null::bigint,null::text,null::text,null::text,null::text,null::timestamptz,null::uuid;
end $$;
create or replace function public.join_queue(qtype text) returns void language plpgsql security definer set search_path='' as $$
declare actor uuid:=safety_private.actor();begin
 if qtype is null or qtype not in('matchmaking','downtime') then raise exception 'Queue unavailable' using errcode='42501';end if;
 if qtype='matchmaking' then
  perform 1 from public.profiles p where p.id=actor for share;
  if not exists(select 1 from active_private.people() p where p.person=actor) then raise exception 'Save current Friends filters and choose a location' using errcode='AQ409';end if;
 end if;
 insert into public.queue_entries(profile_id,queue_type) values(actor,qtype) on conflict(profile_id) do update set queue_type=excluded.queue_type,joined_at=statement_timestamp();
end $$;
revoke all on all functions in schema active_private from public,anon,authenticated;
revoke all on function public.get_queue_match(),public.join_queue(text) from public,anon,authenticated;
grant execute on function public.get_queue_match(),public.join_queue(text) to authenticated;
do $$ declare r text;f record;begin
 foreach r in array array['anon','authenticated'] loop
  if has_schema_privilege(r::name,'active_private','USAGE') then raise exception 'Inherited active schema access' using errcode='42501';end if;
  for f in select p.oid from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='active_private' loop
   if has_function_privilege(r::name,f.oid,'EXECUTE') then raise exception 'Inherited active helper access' using errcode='42501';end if;
  end loop;
 end loop;
 if has_function_privilege('anon','public.get_queue_match()','EXECUTE') or not has_function_privilege('authenticated','public.get_queue_match()','EXECUTE') then raise exception 'Queue read ACL mismatch' using errcode='42501';end if;
end $$;


-- docs/profile-photo-migration.sql

set local lock_timeout='3s';set local statement_timeout='30s';
do $$ begin
 if to_regprocedure('social_private.profile_audience(uuid,uuid)') is null or to_regprocedure('location_private.usable(text,uuid,uuid,text,text)') is null then raise exception 'Photo prerequisites missing' using errcode='22023';end if;
end $$;
create schema photo_private;
revoke all on schema photo_private from public,anon,authenticated;
-- Strict baseline JPEG envelope emitted by the API. No EXIF, XMP, ICC, comments,
-- extra frames, trailing data or metadata-bearing APP segments can bypass the API.
create function photo_private.valid_jpeg(bytes bytea) returns boolean language plpgsql immutable set search_path='' as $$
declare total integer:=octet_length(bytes);pos integer:=2;marker integer;size integer;frame boolean:=false;scan boolean:=false;width integer;height integer;i integer;begin
 if total not between 32 and 262144 or get_byte(bytes,0)<>255 or get_byte(bytes,1)<>216 then return false;end if;
 while pos<total loop
  if get_byte(bytes,pos)<>255 or pos+1>=total then return false;end if;
  marker:=get_byte(bytes,pos+1);pos:=pos+2;
  if marker=217 then return scan and pos=total;end if;
  if scan then
   if marker=0 or marker between 208 and 215 then
    while pos<total and get_byte(bytes,pos)<>255 loop pos:=pos+1;end loop;
    continue;
   end if;
   return false;
  end if;
  if marker not in(192,196,219,218,224) or pos+1>=total then return false;end if;
  size:=get_byte(bytes,pos)*256+get_byte(bytes,pos+1);
  if size<2 or pos+size>total then return false;end if;
  if marker=224 and (size<>16 or substring(bytes from pos+3 for 5)<>decode('4a46494600','hex')) then return false;end if;
  if marker=192 then
   if frame or size<11 or get_byte(bytes,pos+2)<>8 then return false;end if;
   height:=get_byte(bytes,pos+3)*256+get_byte(bytes,pos+4);width:=get_byte(bytes,pos+5)*256+get_byte(bytes,pos+6);
   if width not between 1 and 512 or height not between 1 and 512 or get_byte(bytes,pos+7) not in(1,3) or size<>8+3*get_byte(bytes,pos+7) then return false;end if;
   frame:=true;
  end if;
  pos:=pos+size;
  if marker=218 then
   if not frame or scan then return false;end if;scan:=true;
   while pos<total and get_byte(bytes,pos)<>255 loop pos:=pos+1;end loop;
  end if;
 end loop;
 return false;
exception when data_exception then return false;
end $$;
create table photo_private.photos(
 user_id uuid primary key references auth.users(id) on delete cascade,
 revision bigint not null check(revision between 1 and 9007199254740991),
 jpeg bytea check(jpeg is null or photo_private.valid_jpeg(jpeg)),
 updated_at timestamptz not null default statement_timestamp()
);
create table photo_private.requests(
 user_id uuid not null references auth.users(id) on delete cascade,request_id uuid not null,fingerprint bytea not null,
 revision bigint not null,has_photo boolean not null,created_at timestamptz not null default statement_timestamp(),primary key(user_id,request_id)
);
alter table photo_private.photos enable row level security;alter table photo_private.requests enable row level security;
revoke all on all tables in schema photo_private from public,anon,authenticated;
create function public.get_profile_photo_state() returns jsonb language plpgsql stable security definer set search_path='' as $$
declare actor uuid:=safety_private.actor();result jsonb;begin
 select jsonb_build_object('revision',p.revision,'hasPhoto',p.jpeg is not null,'updatedAt',to_char(p.updated_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')) into result from photo_private.photos p where p.user_id=actor;
 return coalesce(result,'{"revision":0,"hasPhoto":false,"updatedAt":null}');end $$;
create function public.save_profile_photo(photo_in jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=safety_private.actor();expected bigint;key uuid;bytes bytea;fingerprint bytea;prior photo_private.requests;current_photo photo_private.photos;begin
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'READ COMMITTED required' using errcode='25001';end if;
 if jsonb_typeof(photo_in) is distinct from 'object' or (select count(*) from jsonb_object_keys(photo_in))<>3 or not photo_in ?& array['expectedRevision','requestId','jpegBase64']
 or jsonb_typeof(photo_in->'expectedRevision') is distinct from 'number' or jsonb_typeof(photo_in->'requestId') is distinct from 'string' or jsonb_typeof(photo_in->'jpegBase64') not in('null','string') then raise exception 'Invalid photo request' using errcode='22023';end if;
 if (photo_in->>'expectedRevision')::numeric not between 0 and 9007199254740990 or trunc((photo_in->>'expectedRevision')::numeric)<>(photo_in->>'expectedRevision')::numeric or not location_private.valid_uuid(photo_in->>'requestId') or char_length(photo_in->>'jpegBase64')>349528 then raise exception 'Invalid photo values' using errcode='22023';end if;
 expected:=(photo_in->>'expectedRevision')::bigint;key:=(photo_in->>'requestId')::uuid;
 begin bytes:=decode(photo_in->>'jpegBase64','base64');exception when data_exception then raise exception 'Invalid photo encoding' using errcode='22023';end;
 if bytes is not null and not photo_private.valid_jpeg(bytes) then raise exception 'Only sanitized baseline photo JPEG is accepted' using errcode='22023';end if;
 fingerprint:=sha256(convert_to(photo_in::text,'UTF8'));
 perform pg_advisory_xact_lock(hashtextextended('pebble.photo.owner.v1:'||actor::text,0));
 select * into prior from photo_private.requests r where r.user_id=actor and r.request_id=key;
 if found then
  if prior.fingerprint<>fingerprint then raise exception 'Photo request changed' using errcode='PH409';end if;
  -- A later edit cannot be mistaken for confirmation of the replayed mutation.
  select * into current_photo from photo_private.photos p where p.user_id=actor;
  if current_photo.revision<>prior.revision then raise exception 'Photo changed after this request' using errcode='PH409';end if;
  return public.get_profile_photo_state();
 end if;
 select * into current_photo from photo_private.photos p where p.user_id=actor for update;
 if coalesce(current_photo.revision,0)<>expected then raise exception 'Photo revision conflict' using errcode='PH409';end if;
 -- Removing an actual saved image is never blocked by an upload quota. Empty
 -- redundant removals are bounded separately; they cannot grow the ledger freely.
 if bytes is not null then
  if (select count(*) from photo_private.requests r where r.user_id=actor and r.has_photo and r.created_at>statement_timestamp()-interval '1 hour')>=5
  or (select count(*) from photo_private.requests r where r.user_id=actor and r.has_photo and r.created_at>statement_timestamp()-interval '24 hours')>=20 then raise exception 'Photo upload limit' using errcode='PH429';end if;
 elsif current_photo.jpeg is null then
  if (select count(*) from photo_private.requests r where r.user_id=actor and not r.has_photo and r.created_at>statement_timestamp()-interval '1 hour')>=5
  or (select count(*) from photo_private.requests r where r.user_id=actor and not r.has_photo and r.created_at>statement_timestamp()-interval '24 hours')>=20 then raise exception 'Empty photo change limit' using errcode='PH429';end if;
 end if;
 insert into photo_private.photos(user_id,revision,jpeg) values(actor,expected+1,bytes) on conflict(user_id) do update set revision=excluded.revision,jpeg=excluded.jpeg,updated_at=statement_timestamp();
 insert into photo_private.requests(user_id,request_id,fingerprint,revision,has_photo) values(actor,key,fingerprint,expected+1,bytes is not null);
 return public.get_profile_photo_state();
end $$;
-- History membership alone is not a current photo audience. Dating adds its
-- own reciprocal current audience when that reviewed candidate is installed.
create function photo_private.audience(viewer uuid,owner uuid) returns boolean language sql stable security definer set search_path='' as $$
 select viewer=owner or (public.safety_pair_allowed(viewer,owner) and (social_private.profile_audience(viewer,owner) or (social_private.friends_discoverable(viewer) and social_private.friends_discoverable(owner))));
$$;
create function photo_private.lock_audience(viewer uuid,owner uuid) returns void language plpgsql volatile security definer set search_path='' as $$
begin
 if viewer<>owner then perform social_private.lock_pair(viewer,owner);end if;
 perform 1 from public.account_settings s where s.user_id in(viewer,owner) order by s.user_id for share;
 perform 1 from public.detailed_settings s where s.user_id in(viewer,owner) order by s.user_id for share;
end $$;
create function public.get_profile_photo_reference(owner_in uuid) returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare actor uuid:=safety_private.actor();result jsonb;begin
 if owner_in is null then raise exception 'Invalid photo owner' using errcode='22023';end if;
 perform photo_private.lock_audience(actor,owner_in);
 perform 1 from photo_private.photos p where p.user_id=owner_in for share;
 if not photo_private.audience(actor,owner_in) then raise exception 'Photo unavailable' using errcode='PT404';end if;
 select jsonb_build_object('revision',p.revision,'hasPhoto',p.jpeg is not null,'updatedAt',null) into result from photo_private.photos p where p.user_id=owner_in;
 return coalesce(result,'{"revision":0,"hasPhoto":false,"updatedAt":null}');end $$;
create function public.read_profile_photo(owner_in uuid,revision_in bigint) returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare actor uuid:=safety_private.actor();result jsonb;begin
 if owner_in is null or revision_in is null or revision_in<0 then raise exception 'Invalid photo read' using errcode='22023';end if;
 perform photo_private.lock_audience(actor,owner_in);
 perform 1 from photo_private.photos p where p.user_id=owner_in for share;
 if not photo_private.audience(actor,owner_in) then raise exception 'Photo unavailable' using errcode='PT404';end if;
 select jsonb_build_object('revision',p.revision,'jpegBase64',encode(p.jpeg,'base64')) into result from photo_private.photos p where p.user_id=owner_in and p.jpeg is not null and (revision_in=0 or p.revision=revision_in);
 if result is null then raise exception 'Photo unavailable' using errcode='PT404';end if;
 return result;end $$;
revoke all on all functions in schema photo_private from public,anon,authenticated;
revoke all on function public.get_profile_photo_state(),public.save_profile_photo(jsonb),public.read_profile_photo(uuid,bigint),public.get_profile_photo_reference(uuid) from public,anon,authenticated;
grant execute on function public.get_profile_photo_state(),public.save_profile_photo(jsonb),public.read_profile_photo(uuid,bigint),public.get_profile_photo_reference(uuid) to authenticated;
do $$ declare r text;f record;t text;signature text;begin
 foreach r in array array['anon','authenticated'] loop
  if has_schema_privilege(r::name,'photo_private','USAGE') then raise exception 'Inherited photo schema access' using errcode='42501';end if;
  foreach t in array array['photos','requests'] loop
   if has_table_privilege(r::name,'photo_private.'||t,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') or has_any_column_privilege(r::name,'photo_private.'||t,'SELECT,INSERT,UPDATE,REFERENCES') then raise exception 'Inherited photo data access' using errcode='42501';end if;
  end loop;
  for f in select p.oid from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='photo_private' loop
   if has_function_privilege(r::name,f.oid,'EXECUTE') then raise exception 'Inherited photo helper access' using errcode='42501';end if;
  end loop;
 end loop;
 foreach signature in array array['public.get_profile_photo_state()','public.save_profile_photo(jsonb)','public.read_profile_photo(uuid,bigint)','public.get_profile_photo_reference(uuid)'] loop
  if has_function_privilege('anon',signature,'EXECUTE') or not has_function_privilege('authenticated',signature,'EXECUTE') then raise exception 'Inherited photo RPC access' using errcode='42501';end if;
 end loop;
end $$;


-- docs/dating-live-migration.sql

set local lock_timeout='3s';set local statement_timeout='30s';
do $$ begin
 if to_regclass('photo_private.photos') is null or to_regprocedure('public.dating_reciprocal_targets(jsonb,jsonb)') is null or to_regprocedure('social_private.profile_audience(uuid,uuid)') is null then raise exception 'Real Dating prerequisites missing' using errcode='22023';end if;
end $$;
create schema dating_private;
revoke all on schema dating_private from public,anon,authenticated;
create function dating_private.eligible(person uuid) returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.dating_owner_aggregates d join public.profiles p on p.id=d.user_id join public.detailed_settings s on s.user_id=p.id
 where p.id=person and social_private.discoverable(person) and s.settings->>'datingDiscovery'='true' and public.valid_dating_profile(d.profile) and public.dating_complete(d.profile)
 and public.dating_adult_on(p.birthdate,public.dating_campus_date(statement_timestamp())) and d.search<>'null'::jsonb and public.valid_dating_search(d.search)
 and location_private.usable('dating',(d.search->'searchArea'->>'resolvedLocationRef')::uuid,person,d.search->'searchArea'->>'source',case when d.search->'searchArea'->>'source'='home' then p.location_city else d.search->'searchArea'->>'areaLabel' end));
$$;
create function dating_private.people() returns table(person uuid,profile jsonb,search jsonb,birthdate date,latitude double precision,longitude double precision)
language sql stable security definer set search_path='' as $$
 select d.user_id,d.profile,d.search,p.birthdate,r.latitude,r.longitude from public.dating_owner_aggregates d join auth.users u on u.id=d.user_id join public.profiles p on p.id=d.user_id
 join public.dating_search_location_refs r on r.id=(d.search->'searchArea'->>'resolvedLocationRef')::uuid and r.user_id=d.user_id
 where d.profile->>'enabled'='true' and dating_private.eligible(d.user_id);
$$;
create function dating_private.ranking(actor uuid) returns table(person uuid,distance_miles double precision,interest_count bigint)
language sql stable security definer set search_path='' as $$
 with pool as materialized(select * from dating_private.people()),pairs as(
 select other.*,mine.birthdate mine_dob,mine.search mine_search,
  2*(6371.0088/1.609344)*asin(sqrt(least(1::double precision,greatest(0::double precision,power(sin(radians(other.latitude-mine.latitude)/2),2)+cos(radians(mine.latitude))*cos(radians(other.latitude))*power(sin(radians(other.longitude-mine.longitude)/2),2))))) distance
 from pool mine cross join pool other where mine.person=actor and other.person<>actor and public.safety_pair_allowed(actor,other.person)
 and public.dating_reciprocal_targets(mine.profile,other.profile))
 select pair.person,pair.distance,(select count(distinct public.profile_language_key(a.text)) from public.user_interests a where a.profile_id=actor and exists(select 1 from public.user_interests b where b.profile_id=pair.person and public.profile_language_key(b.text)=public.profile_language_key(a.text)))
 from pairs pair where extract(year from age(public.dating_campus_date(statement_timestamp()),pair.birthdate)) between (pair.mine_search->>'ageMin')::integer and (pair.mine_search->>'ageMax')::integer
 and extract(year from age(public.dating_campus_date(statement_timestamp()),pair.mine_dob)) between (pair.search->>'ageMin')::integer and (pair.search->>'ageMax')::integer
 and pair.distance<=least((pair.mine_search->>'radiusMiles')::integer,(pair.search->>'radiusMiles')::integer)+8*2.220446049250313e-16*greatest(1::double precision,pair.distance);
$$;
create function dating_private.lock_eligibility(a uuid,b uuid) returns void language plpgsql security definer set search_path='' as $$
begin
 perform social_private.lock_pair(a,b);
 perform 1 from public.account_settings s where s.user_id in(a,b) order by s.user_id for share;
 perform 1 from public.detailed_settings s where s.user_id in(a,b) order by s.user_id for share;
 perform 1 from public.dating_search_location_refs r join public.dating_owner_aggregates d on d.user_id=r.user_id and r.id=(d.search->'searchArea'->>'resolvedLocationRef')::uuid where d.user_id in(a,b) order by r.id for share of r;
 perform 1 from location_private.assertions p join public.dating_owner_aggregates d on d.user_id=p.actor_id and p.id=(d.search->'searchArea'->>'resolvedLocationRef')::uuid where p.mode='dating' and d.user_id in(a,b) order by p.id for share of p;
 perform 1 from location_private.places p join location_private.assertions proof on proof.place_id=p.id join public.dating_owner_aggregates d on d.user_id=proof.actor_id and proof.id=(d.search->'searchArea'->>'resolvedLocationRef')::uuid where proof.mode='dating' and d.user_id in(a,b) order by p.id for share of p;
 perform 1 from public.dating_owner_aggregates d where d.user_id in(a,b) order by d.user_id for share;
end $$;
create function public.get_dating_runtime() returns jsonb language plpgsql stable security definer set search_path='' as $$
declare actor uuid:=safety_private.actor();begin
 return jsonb_build_object('available',true,'aggregate',public.get_dating_preferences(),'canStart',dating_private.eligible(actor),
 'globalDiscovery',coalesce((select public.detailed_settings_masters(s.settings)->>'discoverable'='true' from public.account_settings s where s.user_id=actor),false),
 'datingDiscovery',coalesce((select s.settings->>'datingDiscovery'='true' from public.detailed_settings s where s.user_id=actor),false));end $$;
-- Explicit opt-out must remain possible after a location expires. No new reference
-- is introduced and the unchanged saved selection stays ineligible on future use.
create or replace function location_private.preference_guard() returns trigger language plpgsql security definer set search_path='' as $$
declare search jsonb;mode_in text;label_in text;begin
 if tg_table_name='friends_search_preferences' then search:=new.preferences;mode_in:='friends';else
  if tg_op='UPDATE' and old.profile->>'enabled'='true' and new.profile->>'enabled'='false' and new.search is not distinct from old.search then return new;end if;
  search:=new.search;mode_in:='dating';end if;
 if search->'searchArea'->>'resolvedLocationRef' is null then return new;end if;
 if search->'searchArea'->>'source'='home' then select location_city into label_in from public.profiles where id=new.user_id for share;else label_in:=search->'searchArea'->>'areaLabel';end if;
 if not location_private.usable(mode_in,(search->'searchArea'->>'resolvedLocationRef')::uuid,new.user_id,search->'searchArea'->>'source',label_in) then raise exception 'Search location unavailable' using errcode='LC409';end if;
 return new;end $$;
create function public.set_dating_enabled(change_in jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=safety_private.actor();current_value public.dating_owner_aggregates;key text;begin
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'READ COMMITTED required' using errcode='25001';end if;
 if jsonb_typeof(change_in) is distinct from 'object' or (select count(*) from jsonb_object_keys(change_in))<>3 or not change_in ?& array['expectedProfileRevision','expectedSearchRevision','enabled'] or jsonb_typeof(change_in->'enabled') is distinct from 'boolean' then raise exception 'Invalid Dating consent request' using errcode='22023';end if;
 foreach key in array array['expectedProfileRevision','expectedSearchRevision'] loop
  if jsonb_typeof(change_in->key) is distinct from 'number' or (change_in->>key)::numeric not between 0 and 9007199254740990 or trunc((change_in->>key)::numeric)<>(change_in->>key)::numeric then raise exception 'Invalid Dating revision' using errcode='22023';end if;
 end loop;
 perform 1 from public.profiles p where p.id=actor for share;
 perform 1 from public.account_settings s where s.user_id=actor for share;
 perform 1 from public.detailed_settings s where s.user_id=actor for share;
 perform 1 from public.dating_search_location_refs r join public.dating_owner_aggregates d on d.user_id=r.user_id and r.id=(d.search->'searchArea'->>'resolvedLocationRef')::uuid where d.user_id=actor for share of r;
 select * into current_value from public.dating_owner_aggregates d where d.user_id=actor for update;
 if current_value.user_id is null or current_value.profile_revision<>(change_in->>'expectedProfileRevision')::bigint or current_value.search_revision<>(change_in->>'expectedSearchRevision')::bigint then raise exception 'Dating revisions changed' using errcode='DA409';end if;
 if change_in->>'enabled'='true' and not dating_private.eligible(actor) then raise exception 'Complete adult Dating details, location and discovery first' using errcode='DL409';end if;
 update public.dating_owner_aggregates d set profile=jsonb_set(d.profile,'{enabled}',change_in->'enabled'),profile_revision=d.profile_revision+1,search_revision=d.search_revision+1 where d.user_id=actor;
 return public.get_dating_runtime();end $$;
create function public.find_dating_candidate(excluded_in jsonb) returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare actor uuid:=safety_private.actor();selected uuid;distance double precision;result jsonb;begin
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'READ COMMITTED required' using errcode='25001';end if;
 if jsonb_typeof(excluded_in) is distinct from 'array' or jsonb_array_length(excluded_in)>50 or exists(select 1 from jsonb_array_elements(excluded_in) x where jsonb_typeof(x)<>'string' or not location_private.valid_uuid(x #>> '{}')) or (select count(*)<>count(distinct (value #>> '{}')::uuid) from jsonb_array_elements(excluded_in)) then raise exception 'Invalid excluded profiles' using errcode='22023';end if;
 if not exists(select 1 from dating_private.people() p where p.person=actor) then raise exception 'Start eligible Dating discovery before searching' using errcode='DL409';end if;
 select r.person into selected from dating_private.ranking(actor) r where not exists(select 1 from jsonb_array_elements_text(excluded_in) x where x::uuid=r.person)
 order by r.distance_miles,r.interest_count desc,r.person limit 1;
 if selected is null then return '{"candidate":null}';end if;
 perform dating_private.lock_eligibility(actor,selected);
 select r.distance_miles into distance from dating_private.ranking(actor) r where r.person=selected;
 if not found then return '{"candidate":null}';end if;
 select jsonb_build_object('id',p.id,'name',p.display_name,'age',extract(year from age(public.dating_campus_date(statement_timestamp()),p.birthdate))::integer,'city',p.location_city,'bio',p.bio,
 'avatar',case when photo.user_id is null then p.avatar_url else null end,'photoRevision',case when photo.jpeg is null then 0 else photo.revision end,
 'interests',coalesce((select jsonb_agg(i.text order by i.text collate "C") from public.user_interests i where i.profile_id=p.id),'[]'),
 'areaDistanceMiles',ceil(distance)::integer,'heightInches',case when d.profile->'visibility'->>'height'='true' then (d.profile->>'heightInches')::integer else null end,
 'gender',case when d.profile->'visibility'->>'gender'='true' then d.profile->>'gender' else null end,'sexuality',case when d.profile->'visibility'->>'sexuality'='true' then d.profile->>'sexuality' else null end,
 'intent',d.profile->>'intent','style',d.profile->>'style') into result from public.profiles p join public.dating_owner_aggregates d on d.user_id=p.id left join photo_private.photos photo on photo.user_id=p.id where p.id=selected;
 return jsonb_build_object('candidate',result);end $$;
create function public.request_dating_connection(target_in uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=safety_private.actor();begin
 if target_in is null or target_in=actor then raise exception 'Invalid Dating target' using errcode='22023';end if;
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'READ COMMITTED required' using errcode='25001';end if;
 perform dating_private.lock_eligibility(actor,target_in);
 if not exists(select 1 from dating_private.ranking(actor) r where r.person=target_in) then raise exception 'Dating connection unavailable' using errcode='DL409';end if;
 return public.social_connection(target_in,'request');end $$;
create or replace function photo_private.audience(viewer uuid,owner uuid) returns boolean language sql stable security definer set search_path='' as $$
 select viewer=owner or (public.safety_pair_allowed(viewer,owner) and (social_private.profile_audience(viewer,owner) or (social_private.friends_discoverable(viewer) and social_private.friends_discoverable(owner)) or exists(select 1 from dating_private.ranking(viewer) r where r.person=owner)));
$$;
-- Photo metadata and bytes use the same current Dating eligibility fence as
-- candidates/requests, including pause, reciprocal filters and catalogue expiry.
create or replace function photo_private.lock_audience(viewer uuid,owner uuid) returns void language plpgsql volatile security definer set search_path='' as $$
begin
 if viewer<>owner then perform dating_private.lock_eligibility(viewer,owner);
 else
  perform 1 from public.account_settings s where s.user_id=viewer for share;
  perform 1 from public.detailed_settings s where s.user_id=viewer for share;
 end if;
end $$;
revoke all on function photo_private.lock_audience(uuid,uuid) from public,anon,authenticated;
revoke all on all functions in schema dating_private from public,anon,authenticated;
revoke all on function public.get_dating_runtime(),public.set_dating_enabled(jsonb),public.find_dating_candidate(jsonb),public.request_dating_connection(uuid) from public,anon,authenticated;
grant execute on function public.get_dating_runtime(),public.set_dating_enabled(jsonb),public.find_dating_candidate(jsonb),public.request_dating_connection(uuid) to authenticated;
do $$ declare role_in text;f record;signature text;begin
 foreach role_in in array array['anon','authenticated'] loop
  if has_schema_privilege(role_in::name,'dating_private','USAGE') then raise exception 'Inherited Dating helper access' using errcode='42501';end if;
  for f in select p.oid from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='dating_private' loop
   if has_function_privilege(role_in::name,f.oid,'EXECUTE') then raise exception 'Inherited Dating helper execute' using errcode='42501';end if;
  end loop;
 end loop;
 foreach signature in array array['public.get_dating_runtime()','public.set_dating_enabled(jsonb)','public.find_dating_candidate(jsonb)','public.request_dating_connection(uuid)'] loop
  if has_function_privilege('anon',signature,'EXECUTE') or not has_function_privilege('authenticated',signature,'EXECUTE') then raise exception 'Inherited Dating RPC access' using errcode='42501';end if;
 end loop;
end $$;


-- docs/real-account-boundary.sql

set local lock_timeout='3s';
do $$ begin
 if not exists(select 1 from pg_attribute where attrelid='auth.users'::regclass and attname='is_anonymous' and atttypid='boolean'::regtype and not attisdropped)
 or to_regprocedure('social_private.discoverable(uuid)') is null then raise exception 'Reviewed non-anonymous Auth prerequisite missing' using errcode='22023';end if;
 if not exists(select 1 from pg_proc where oid='safety_private.actor()'::regprocedure and pg_get_userbyid(proowner)=current_user)
 or not exists(select 1 from pg_proc where oid='social_private.discoverable(uuid)'::regprocedure and pg_get_userbyid(proowner)=current_user)
 or not exists(select 1 from pg_proc where oid='safety_private.contact_allowed(uuid,uuid)'::regprocedure and pg_get_userbyid(proowner)=current_user) then raise exception 'Actor helper owner mismatch' using errcode='42501';end if;
end $$;
create or replace function safety_private.actor() returns uuid language plpgsql stable set search_path='' as $$
declare actor uuid:=auth.uid();begin
 if actor is null or not exists(select 1 from auth.users u where u.id=actor and u.is_anonymous is false) then raise exception 'Verified signed-in account required' using errcode='28000';end if;
 return actor;end $$;
create or replace function social_private.discoverable(person uuid) returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.profiles p join public.account_settings a on a.user_id=p.id
 where p.id=person and p.is_active and exists(select 1 from auth.users u where u.id=p.id and u.is_anonymous is false) and public.detailed_settings_masters(a.settings)->>'discoverable'='true'
 and p.birthdate between date '0001-01-01' and date '9999-12-31'
 and p.birthdate<=(statement_timestamp() at time zone 'America/New_York')::date-interval '18 years'
 and char_length(p.username) between 1 and 80 and char_length(p.display_name) between 1 and 120
 and public.profile_language_key(p.username)<>'' and public.profile_language_key(p.display_name)<>''
 and coalesce(char_length(p.bio),0)<=1000 and char_length(p.location_city)<=120 and public.profile_language_key(p.location_city)<>''
 and (select count(*) from public.user_interests i where i.profile_id=p.id) between 3 and 30
 and not exists(select 1 from public.user_interests i where i.profile_id=p.id and (char_length(i.text)>120 or public.profile_language_key(i.text)=''))
 and (select count(*) from public.availability w where w.profile_id=p.id) between 1 and 56
 and not exists(select 1 from public.availability w where w.profile_id=p.id and (w.start_time::text !~ '^(([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9])$' or w.end_time::text !~ '^(([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9]|24:00:00)$'))
 and not exists(select 1 from public.availability w join public.availability x on x.profile_id=w.profile_id and x.id>w.id where w.profile_id=p.id and w.dow=x.dow and w.start_time<x.end_time and x.start_time<w.end_time)
 and jsonb_typeof(a.preferences->'intents')='array' and jsonb_array_length(a.preferences->'intents') between 1 and 20
 and not exists(select 1 from jsonb_array_elements(a.preferences->'intents') item where jsonb_typeof(item)<>'string' or char_length(item #>> '{}')>120 or public.profile_language_key(item #>> '{}')='')
 and a.preferences->>'distance' in('Nearby','5 miles','10 miles') and a.preferences->>'group' in('One-on-one','Small groups','Either'));
$$;
create or replace function safety_private.contact_allowed(a uuid,b uuid) returns boolean language sql stable security definer set search_path='' as $$
 select public.safety_pair_allowed(a,b) and (select count(*)=2 from auth.users u where u.id in(a,b) and u.is_anonymous is false)
 and exists(select 1 from public.connections c where c.user_a=least(a,b) and c.user_b=greatest(a,b) and c.status='accepted'
 and not exists(select 1 from safety_private.revoked_connections r where r.connection_id=c.id));
$$;
revoke all on function safety_private.actor(),social_private.discoverable(uuid),safety_private.contact_allowed(uuid,uuid) from public,anon,authenticated;
do $$ declare r text;begin
 foreach r in array array['anon','authenticated'] loop
  if has_function_privilege(r::name,'safety_private.actor()','EXECUTE') or has_function_privilege(r::name,'social_private.discoverable(uuid)','EXECUTE') or has_function_privilege(r::name,'safety_private.contact_allowed(uuid,uuid)','EXECUTE') then raise exception 'Inherited actor helper bypass' using errcode='42501';end if;
 end loop;
end $$;


